import { AdminPage } from "@/components/admin-page";

export default function Page() {
  return <AdminPage />;
}

"use client";

import { FilterIcon } from "lucide-react";
import { useState } from "react";
import {
  activeCount,
  CREATED_PRESETS,
  createdOf,
  createdPatch,
  defaultDirection,
  directionLabel,
  FILTERS,
  type FilterKey,
  filterDef,
  OPTIONS,
  type OptionKey,
  SORT_KEYS,
  type SortState,
  STATUS_OPERATORS,
  STATUSES,
  type StatusOperator,
  sortLabel,
  statusLabel,
  type UserFilters,
  type UserSortKey,
} from "@/components/admin-filters";
import {
  DATE_OPERATORS,
  type DateOperator,
  dateOperatorLabel,
  setDateOperator,
  TODAY,
} from "@/components/date-filter";
import { DateFilterStep } from "@/components/date-filter-step";
import {
  AppliedRow,
  COLLAPSE_MS,
  Collapse,
  ColumnChecklist,
  DrawerSection,
  type DrawerView,
  DrilldownList,
  DrilldownRow,
  FILTER_SHEET,
  FilterOption,
  GROUP,
  type OperatorHandle,
  OperatorSheet,
  Options,
  SetChecklist,
  StepHeader,
  ViewSection,
} from "@/components/drawer-parts";
import { directionsFor, type SortDirection } from "@/components/sort";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Drawer,
  DrawerContent,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";
import { RadioGroup } from "@/components/ui/radio-group";
import {
  Stepper,
  StepperContent,
  StepperStep,
  useStepper,
} from "@/components/ui/stepper";
import { useReducedMotion } from "@/components/use-reduced-motion";

interface AdminFiltersDrawerProps<C extends string> {
  filters: UserFilters;
  onChange: (patch: Partial<UserFilters>) => void;
  onSortChange: (sort: SortState) => void;
  sort: SortState;
  /** Columns and Export, which the desktop shows beside Sort. */
  view: DrawerView<C>;
}

/**
 * The steps before Created, in `FILTERS` order — the menu's rows drill into
 * them by position. Status is a set with an operator; the rest are radios.
 */
const LIST_STEPS: readonly (OptionKey | "status")[] = [
  "role",
  "status",
  "seats",
  "twoFactor",
];

/** The filters here with a comparison to choose. */
type UserOperatorKey = "created" | "status";

/**
 * The phone half of the users toolbar — the same bottom sheet and `Stepper`
 * drilldown as the payments one, because the two tables are one design.
 *
 * Desktop has the pills; below `sm` they would wrap into a column that buries
 * the table, so the whole filter set folds in here: a menu of "label + current
 * value" rows that each open one screen. The rows come from `FILTERS`, the same
 * descriptors the pills read, so a row and its pill cannot disagree.
 *
 * No `swipeDirection`: the primitive's default is `down`, which supplies the
 * bottom-sheet geometry and the drag handle.
 *
 * Filters apply live; `Apply` only dismisses. There is no draft state to
 * reconcile, and on a large phone the table is visible behind the sheet.
 */
export function AdminFiltersDrawer<C extends string>({
  filters,
  onChange,
  onSortChange,
  sort,
  view,
}: AdminFiltersDrawerProps<C>) {
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const count = activeCount(filters);

  // The key outlives `sheetOpen` so the sheet keeps its options while it
  // slides away.
  const [sheetKey, setSheetKey] = useState<UserOperatorKey>("status");
  const [sheetOpen, setSheetOpen] = useState(false);

  const operatorFor = (key: UserOperatorKey) =>
    key === "created"
      ? {
          label: dateOperatorLabel(createdOf(filters).op),
          options: DATE_OPERATORS,
          select: (next: string) =>
            onChange(
              createdPatch(
                setDateOperator(createdOf(filters), next as DateOperator, TODAY)
              )
            ),
          value: createdOf(filters).op as string,
        }
      : {
          label:
            STATUS_OPERATORS.find((item) => item.value === filters.statusOp)
              ?.label ?? "",
          options: STATUS_OPERATORS.map((item) => ({
            label: item.label.charAt(0).toUpperCase() + item.label.slice(1),
            value: item.value,
          })),
          select: (next: string) =>
            onChange({ statusOp: next as StatusOperator }),
          value: filters.statusOp as string,
        };

  const handle = (key: UserOperatorKey): OperatorHandle => ({
    label: operatorFor(key).label,
    onOpen: () => {
      setSheetKey(key);
      setSheetOpen(true);
    },
  });
  const sheet = operatorFor(sheetKey);

  // Clears the value and keeps the operator, as the desktop popovers do; the
  // applied row's ✕ is what removes the filter outright.
  const clearFor = (key: FilterKey) => {
    const def = filterDef(key);
    return def.value(filters) === null
      ? undefined
      : () => onChange(def.clearValue ? def.clearValue(filters) : def.clear);
  };

  return (
    <Drawer
      onOpenChange={(isOpen) => {
        setOpen(isOpen);
        if (!isOpen) {
          setStep(0);
        }
      }}
      open={open}
    >
      {/* The count is on the trigger because the pills are hidden at this
          width — without it a filtered table gives no sign of being filtered.
          Sort is deliberately not counted: it is not a filter, and a badge that
          ticks up when you reorder a column is lying. */}
      <DrawerTrigger render={<Button size="sm" variant="outline" />}>
        <FilterIcon className="size-4" />
        Filters
        {count > 0 && <Badge variant="secondary">{count}</Badge>}
      </DrawerTrigger>
      <DrawerContent className={FILTER_SHEET}>
        <div className="w-full">
          <Stepper onValueChange={setStep} value={step}>
            {/* The sheet is a fixed height, so a step's height has nothing
                to animate. */}
            <StepperContent animateHeight={false}>
              <StepperStep>
                <DrawerHeader>
                  <DrawerTitle className="text-center">Filters</DrawerTitle>
                </DrawerHeader>
                <UserFilterMenu
                  handle={handle}
                  filters={filters}
                  onRemove={(key) => onChange(filterDef(key).clear)}
                  sort={sort}
                  view={view}
                />
                {/* No `Clear all` here: each applied row carries its own ✕,
                    and a button that wipes every filter at once sat one slip
                    of the thumb from `Apply`. The toolbar keeps one. */}
                <DrawerFooter>
                  <Button className="w-full" onClick={() => setOpen(false)}>
                    Apply
                  </Button>
                </DrawerFooter>
              </StepperStep>

              {LIST_STEPS.map((key) =>
                key === "status" ? (
                  <StepperStep key={key}>
                    <StepHeader
                      onBack={() => setStep(0)}
                      onClear={clearFor("status")}
                      operator={handle("status")}
                      title="Status"
                    />
                    <SetChecklist
                      items={STATUSES}
                      label={statusLabel}
                      onChange={(next) => onChange({ statuses: next })}
                      value={filters.statuses}
                    />
                  </StepperStep>
                ) : (
                  <StepperStep key={key}>
                    <StepHeader
                      onBack={() => setStep(0)}
                      title={
                        FILTERS.find((def) => def.key === key)?.label ?? key
                      }
                    />
                    <Options
                      onValueChange={(value) => onChange({ [key]: value })}
                      value={filters[key]}
                    >
                      {OPTIONS[key].map((option) => (
                        <FilterOption
                          key={option.value}
                          label={option.label}
                          value={option.value}
                        />
                      ))}
                    </Options>
                  </StepperStep>
                )
              )}

              <StepperStep>
                <StepHeader
                  onBack={() => setStep(0)}
                  onClear={clearFor("created")}
                  operator={handle("created")}
                  title="Created"
                />
                <DateFilterStep
                  filter={createdOf(filters)}
                  onChange={(next) => onChange(createdPatch(next))}
                  presets={CREATED_PRESETS}
                  surface="sheet"
                  today={TODAY}
                />
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Sort" />
                <div className="pb-4">
                  <RadioGroup
                    className={`gap-0 ${GROUP}`}
                    onValueChange={(value) => {
                      if (value) {
                        const key = value as UserSortKey;
                        onSortChange({ direction: defaultDirection(key), key });
                      }
                    }}
                    value={sort.key}
                  >
                    {SORT_KEYS.map((option) => (
                      <FilterOption
                        key={option.id}
                        label={option.label}
                        value={option.id}
                      />
                    ))}
                  </RadioGroup>
                  <RadioGroup
                    className={`mt-3 gap-0 ${GROUP}`}
                    onValueChange={(value) => {
                      if (value) {
                        onSortChange({
                          direction: value as SortDirection,
                          key: sort.key,
                        });
                      }
                    }}
                    value={sort.direction}
                  >
                    {directionsFor(defaultDirection(sort.key)).map(
                      (direction) => (
                        <FilterOption
                          key={direction}
                          label={directionLabel(sort.key, direction)}
                          value={direction}
                        />
                      )
                    )}
                  </RadioGroup>
                </div>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Columns" />
                <ColumnChecklist view={view} />
              </StepperStep>
            </StepperContent>
          </Stepper>
          <OperatorSheet
            onOpenChange={setSheetOpen}
            onSelect={sheet.select}
            open={sheetOpen}
            options={sheet.options}
            title={filterDef(sheetKey).label}
            value={sheet.value}
          />
        </div>
      </DrawerContent>
    </Drawer>
  );
}

/**
 * The drilldown menu: what is applied, then everything there is — the same
 * shape as the payments menu. Generated from the descriptors so a row and its
 * step cannot disagree about their order. Sort is appended by hand because it
 * is not a filter and is not in `FILTERS`.
 */
function UserFilterMenu<C extends string>({
  filters,
  handle,
  onRemove,
  sort,
  view,
}: {
  filters: UserFilters;
  handle: (key: UserOperatorKey) => OperatorHandle;
  onRemove: (key: FilterKey) => void;
  sort: SortState;
  view: DrawerView<C>;
}) {
  const { goTo } = useStepper();
  // Step 0 is the menu itself, so the first filter is step 1.
  const steps = FILTERS.map((def, index) => ({ def, step: index + 1 }));
  const applied = steps.flatMap(({ def, step }) => {
    // Listed while it holds a value; shown beside its badge as the operand
    // where it has one, which `is empty` does not.
    if (def.value(filters) === null) {
      return [];
    }
    const value = def.operand ? def.operand(filters) : def.value(filters);
    return [{ def, step, value }];
  });
  // The row on its way out: it collapses first, and is removed — its filter
  // cleared — once the collapse is done, so the rows below slide up into its
  // place instead of jumping.
  const [leaving, setLeaving] = useState<FilterKey | null>(null);
  const reduced = useReducedMotion();
  const remove = (key: FilterKey) => {
    if (leaving) {
      return;
    }
    setLeaving(key);
    // Under reduced motion the collapse is instant, so nothing to wait for.
    window.setTimeout(
      () => {
        onRemove(key);
        setLeaving(null);
      },
      reduced ? 0 : COLLAPSE_MS
    );
  };
  // Removing the last one closes the whole section, header and all.
  const sectionOpen = !(applied.length === 1 && applied[0].def.key === leaving);

  return (
    <>
      {applied.length > 0 && (
        <Collapse open={sectionOpen}>
          <DrawerSection label="Applied filters">
            <DrilldownList>
              {applied.map(({ def, step, value }) => (
                <Collapse
                  key={def.key}
                  open={def.key !== leaving || !sectionOpen}
                >
                  <AppliedRow
                    label={def.label}
                    onEdit={() => goTo(step)}
                    onRemove={() => remove(def.key)}
                    operator={
                      def.key === "created" || def.key === "status"
                        ? handle(def.key)
                        : undefined
                    }
                    value={value}
                  />
                </Collapse>
              ))}
            </DrilldownList>
          </DrawerSection>
        </Collapse>
      )}
      <DrawerSection label="All filters">
        <DrilldownList>
          {steps.map(({ def, step }) => (
            <DrilldownRow
              key={def.key}
              label={def.label}
              onClick={() => goTo(step)}
            />
          ))}
        </DrilldownList>
      </DrawerSection>
      {/* Sort follows the filter steps, and Columns follows Sort. */}
      <ViewSection
        onColumns={() => goTo(steps.length + 2)}
        onSort={() => goTo(steps.length + 1)}
        sortValue={sortLabel(sort)}
        view={view}
      />
    </>
  );
}

import { type CsvColumn, toCsv } from "@/components/csv";
import {
  clearDateValue,
  type DateFilter,
  type DateOperator,
  dateFilterFromParams,
  dateFilterToParams,
  dateFilterValue,
  dateOperand,
  datePresets,
  dateQualifier,
  EMPTY_DATE_FILTER,
  matchesDate,
  TODAY,
} from "@/components/date-filter";
import {
  addableKeys as addableKeysOf,
  visibleKeys as visibleKeysOf,
} from "@/components/filter-row";
import {
  type Role,
  type Status,
  statusLabels,
  type User,
} from "@/components/mock-admin";
import type {
  SortState as BaseSortState,
  SortDirection,
} from "@/components/sort";
import {
  oneOf,
  pageFromParams,
  pageToParams,
  sortFromParam,
  sortToParam,
} from "@/components/url-params";
import type { DataTableQuery } from "@/components/use-data-table";

/**
 * The users table's filter and sort vocabulary, owned in one place.
 *
 * The pills, the phone drawer, the URL and the page all need the same option
 * lists and labels. One owner, imported each way, is what keeps an option
 * added to one of them from going missing in another. It is the same shape as
 * `payment-filters.ts`, so both toolbars are one design over two vocabularies.
 */

export type RoleFilter = "all" | Role;
/**
 * Status is a set with an operator, the same as the payments Status: "every
 * account but the suspended ones" is the question as often as "only the
 * suspended ones".
 */
export type StatusOperator = "is" | "isNot";
export type SeatsFilter = "all" | "none" | "one" | "many";
export type TwoFactorFilter = "all" | "off" | "on";

export const ROLES: readonly Role[] = ["Admin", "Billing", "Member", "Viewer"];
export const STATUSES: readonly Status[] = ["active", "invited", "suspended"];

/** Shared by the table's Status cell and the detail view, so they cannot drift. */
export const STATUS_VARIANT: Record<
  Status,
  "default" | "outline" | "secondary"
> = {
  active: "secondary",
  invited: "outline",
  suspended: "outline",
};

export interface UserFilters {
  createdAfter: string;
  createdBefore: string;
  createdOp: DateOperator;
  /** A relative rule, `past.7.day` — see `date-filter.ts`. */
  createdRel: string;
  role: RoleFilter;
  search: string;
  seats: SeatsFilter;
  statuses: readonly Status[];
  statusOp: StatusOperator;
  twoFactor: TwoFactorFilter;
}

export const EMPTY_FILTERS: UserFilters = {
  createdAfter: "",
  createdBefore: "",
  createdOp: "between",
  createdRel: "",
  role: "all",
  search: "",
  seats: "all",
  statuses: [],
  statusOp: "is",
  twoFactor: "all",
};

export const STATUS_OPERATORS: readonly {
  label: string;
  value: StatusOperator;
}[] = [
  { label: "is", value: "is" },
  { label: "is not", value: "isNot" },
];

export function statusLabel(status: Status): string {
  return statusLabels[status];
}

/**
 * Each single-select filter's options, `All` first. The pills and the drawer
 * both list these, so the two cannot offer different choices.
 *
 * The unset value reads as a bare "All" because the pill already says which
 * dimension it belongs to — "Role: All roles" would say it twice.
 */
export const OPTIONS = {
  role: [
    { label: "All", value: "all" },
    ...ROLES.map((role) => ({ label: role, value: role })),
  ],
  seats: [
    { label: "All", value: "all" },
    { label: "No seats", value: "none" },
    { label: "One seat", value: "one" },
    { label: "More than one", value: "many" },
  ],
  twoFactor: [
    { label: "All", value: "all" },
    { label: "Enabled", value: "on" },
    { label: "Not enabled", value: "off" },
  ],
} as const satisfies Record<
  "role" | "seats" | "twoFactor",
  readonly { label: string; value: string }[]
>;

export type OptionKey = keyof typeof OPTIONS;

function optionLabel(key: OptionKey, value: string): string | null {
  return value === "all"
    ? null
    : (OPTIONS[key].find((option) => option.value === value)?.label ?? null);
}

/**
 * The Created presets. Sign-ups are read over longer windows than payments —
 * a month's growth, a year's — so these run to the year rather than the day.
 */
export const CREATED_PRESETS = datePresets([
  { count: 30, dir: "past", unit: "day" },
  { count: 90, dir: "past", unit: "day" },
  { count: 12, dir: "past", unit: "month" },
  { dir: "this", unit: "year" },
]);

/** The Created filter as the date filter reads it. */
export function createdOf(f: {
  createdAfter: string;
  createdBefore: string;
  createdOp: DateOperator;
  createdRel: string;
}): DateFilter {
  return {
    after: f.createdAfter,
    before: f.createdBefore,
    op: f.createdOp,
    rel: f.createdRel,
  };
}

/** A date filter back as the fields it is stored in. */
export function createdPatch(filter: DateFilter) {
  return {
    createdAfter: filter.after,
    createdBefore: filter.before,
    createdOp: filter.op,
    createdRel: filter.rel,
  };
}

const CREATED_CLEAR = createdPatch(EMPTY_DATE_FILTER);

// ---------------------------------------------------------------------------
// The pills
// ---------------------------------------------------------------------------

export type FilterKey = "created" | "role" | "seats" | "status" | "twoFactor";

export interface FilterDef {
  /** The patch that resets this filter. */
  clear: Partial<UserFilters>;
  /**
   * Clearing the value but keeping the operator, for a `Clear` inside the
   * filter's editor on either surface. Absent where the two are the same —
   * a filter without an operator. `clear` still resets the operator too: it
   * is what removing the filter does.
   */
  clearValue?: (filters: UserFilters) => Partial<UserFilters>;
  /** What the pill reads when nothing is set. */
  empty: string;
  key: FilterKey;
  /** The dimension, shown muted ahead of the value. */
  label: string;
  /** The value without its comparison, for the phone's applied rows. */
  operand?: (filters: UserFilters) => string | null;
  /** The operator, when it is not the default: "Status is not: Suspended". */
  operator?: (filters: UserFilters) => string | null;
  /** The value, or `null` when the filter is unset. */
  value: (filters: UserFilters) => string | null;
}

/**
 * One descriptor per filter, and the only place a filter is declared. The
 * pills, the drawer's rows and steps, the active count and the URL all derive
 * from this list.
 */
export const FILTERS: readonly FilterDef[] = [
  {
    clear: { role: "all" },
    empty: "All",
    key: "role",
    label: "Role",
    value: (f) => optionLabel("role", f.role),
  },
  {
    clear: { statuses: [], statusOp: "is" },
    clearValue: () => ({ statuses: [] }),
    empty: "All",
    key: "status",
    label: "Status",
    operator: (f) => (f.statusOp === "isNot" ? "is not" : null),
    operand: (f) =>
      f.statuses.length === 0 ? null : f.statuses.map(statusLabel).join(", "),
    // The first pick plus a count of the rest, as the payments pills read.
    value: (f) => {
      if (f.statuses.length === 0) {
        return null;
      }
      const first = statusLabel(f.statuses[0]);
      return f.statuses.length === 1
        ? first
        : `${first}, +${f.statuses.length - 1}`;
    },
  },
  {
    clear: { seats: "all" },
    empty: "All",
    key: "seats",
    label: "Seats",
    value: (f) => optionLabel("seats", f.seats),
  },
  {
    clear: { twoFactor: "all" },
    empty: "All",
    key: "twoFactor",
    label: "Two-factor",
    value: (f) => optionLabel("twoFactor", f.twoFactor),
  },
  {
    clear: CREATED_CLEAR,
    clearValue: (f) => createdPatch(clearDateValue(createdOf(f))),
    empty: "Any",
    key: "created",
    label: "Created",
    operand: (f) => dateOperand(createdOf(f)),
    operator: (f) => dateQualifier(createdOf(f)),
    value: (f) => dateFilterValue(createdOf(f)),
  },
];

/** The two cuts people take first; the rest are added on demand. */
export const DEFAULT_KEYS: readonly FilterKey[] = ["role", "status"];

export function filterDef(key: FilterKey): FilterDef {
  const def = FILTERS.find((item) => item.key === key);
  if (!def) {
    throw new Error(`Unknown filter: ${key}`);
  }
  return def;
}

export function visibleKeys(
  filters: UserFilters,
  added: readonly FilterKey[]
): FilterKey[] {
  return visibleKeysOf(FILTERS, filters, added);
}

export function addableKeys(
  filters: UserFilters,
  added: readonly FilterKey[]
): FilterKey[] {
  return addableKeysOf(FILTERS, filters, added);
}

/** How many filters hold a value — the phone drawer trigger's badge. */
export function activeCount(filters: UserFilters): number {
  return FILTERS.filter((def) => def.value(filters) !== null).length;
}

/** Whether anything at all is applied, search included. */
export function hasActiveFilters(filters: UserFilters): boolean {
  return Boolean(filters.search.trim()) || activeCount(filters) > 0;
}

// ---------------------------------------------------------------------------
// Matching
// ---------------------------------------------------------------------------

type UserMatcher = (user: User, filters: UserFilters) => boolean;

/** One predicate per filter, each returning `true` when the filter is unset. */
const MATCHERS: readonly UserMatcher[] = [
  (user, filters) => {
    const query = filters.search.trim().toLowerCase();
    return (
      !query ||
      user.name.toLowerCase().includes(query) ||
      user.email.toLowerCase().includes(query)
    );
  },
  (user, filters) => filters.role === "all" || user.role === filters.role,
  (user, filters) =>
    filters.statuses.length === 0 ||
    filters.statuses.includes(user.status) === (filters.statusOp === "is"),
  (user, filters) => {
    if (filters.seats === "all") {
      return true;
    }
    if (filters.seats === "none") {
      return user.seats === 0;
    }
    return filters.seats === "one" ? user.seats === 1 : user.seats > 1;
  },
  (user, filters) =>
    filters.twoFactor === "all" ||
    user.twoFactor === (filters.twoFactor === "on"),
  // `createdAt` is an ISO date, so it compares as a string.
  (user, filters) => matchesDate(user.createdAt, createdOf(filters), TODAY),
];

export function matchesUserFilters(user: User, filters: UserFilters): boolean {
  return MATCHERS.every((matches) => matches(user, filters));
}

// ---------------------------------------------------------------------------
// Sort
// ---------------------------------------------------------------------------

export type UserSortKey = "id" | "lastActive" | "name" | "role" | "seats";

/**
 * Always set, like the payments sort. The "Unsorted" option this replaces
 * meant fixture order, which is no order anyone asked for, and it gave the
 * headers a third click that undid the second.
 */
export type SortState = BaseSortState<UserSortKey>;

export const SORT_KEYS: readonly { id: UserSortKey; label: string }[] = [
  { id: "name", label: "Name" },
  { id: "role", label: "Role" },
  { id: "seats", label: "Seats" },
  { id: "lastActive", label: "Last active" },
  { id: "id", label: "ID" },
];

/**
 * What a direction means for the column it applies to. "Ascending" is
 * accurate and says nothing — "A–Z" and "Newest first" say what you will see.
 */
const DIRECTION_LABELS: Record<UserSortKey, Record<SortDirection, string>> = {
  id: { asc: "First added", desc: "Last added" },
  lastActive: { asc: "Oldest first", desc: "Newest first" },
  name: { asc: "A–Z", desc: "Z–A" },
  role: { asc: "A–Z", desc: "Z–A" },
  seats: { asc: "Fewest first", desc: "Most first" },
};

export function directionLabel(
  key: UserSortKey,
  direction: SortDirection
): string {
  return DIRECTION_LABELS[key][direction];
}

/**
 * The direction a column takes when it is first chosen, from the menu or a
 * header. Names read forwards; counts and recency are asked about from the
 * large end.
 */
export function defaultDirection(key: UserSortKey): SortDirection {
  return key === "name" || key === "role" ? "asc" : "desc";
}

export const DEFAULT_SORT: SortState = { direction: "asc", key: "name" };

/** "Name (A–Z)" — the column, then what the order means for it. */
export function sortLabel(sort: SortState): string {
  const key = SORT_KEYS.find((option) => option.id === sort.key)?.label;
  return `${key} (${directionLabel(sort.key, sort.direction)})`;
}

const RELATIVE = /^(\d+|an?) (minute|hour|day|week|month|year)s? ago$/;
const MINUTES = {
  day: 1440,
  hour: 60,
  minute: 1,
  month: 43_200,
  week: 10_080,
  year: 525_600,
} as const;

/**
 * How long ago "Last active" was, in minutes, or `null` for "never".
 *
 * The fixture stores the text the table shows — "2 hours ago" — rather than a
 * timestamp, and that text does not sort: "yesterday" comes after "5 minutes
 * ago" alphabetically. A real table sorts on the timestamp behind the label.
 */
export function minutesAgo(text: string): number | null {
  if (text === "never") {
    return null;
  }
  if (text === "yesterday") {
    return MINUTES.day;
  }
  const match = RELATIVE.exec(text);
  if (!match) {
    return null;
  }
  const count = Number.isNaN(Number(match[1])) ? 1 : Number(match[1]);
  return count * MINUTES[match[2] as keyof typeof MINUTES];
}

/**
 * Users who have never been active have no recency to order by, so they sink
 * to the end in both directions — the same rule as an unfinished payment.
 */
export function sortUsers(rows: readonly User[], sort: SortState): User[] {
  const factor = sort.direction === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    if (sort.key === "lastActive") {
      const left = minutesAgo(a.lastActive);
      const right = minutesAgo(b.lastActive);
      if (left === null || right === null) {
        return Number(left === null) - Number(right === null);
      }
      // Fewer minutes ago is newer, so "Newest first" (desc) is ascending
      // minutes.
      return (right - left) * factor;
    }
    if (sort.key === "seats") {
      return (a.seats - b.seats) * factor;
    }
    return a[sort.key].localeCompare(b[sort.key]) * factor;
  });
}

