/**
 * The users toolbar: the payments toolbar's layout over the users vocabulary.
 *
 * Search, one self-describing pill per filter, `+ Add filter`, Clear all; at
 * the far end Columns, Export and Sort. Below `sm`, search and a Filters
 * drawer. See `AdminPaymentsToolbar` for the reasoning — the point of this
 * file is that there is none of its own to give.
 */
export function AdminUsersToolbar({
  columns,
  table,
}: {
  columns: readonly { id: UserColumnId; label: string }[];
  table: UsersTableState;
}) {
  // One export, the same rows wherever it is asked for: every filtered and
  // sorted row, not the page — and off while a request is in flight, or it
  // would write the rows the last query returned.
  const exportCsv = () =>
    downloadCsv("users.csv", toUsersCsv(table.result.all));
  const exportDisabled = table.loading || table.result.total === 0;
  const { added, filters, patchFilters } = table;
  const row = usePillRow({
    onAdd: table.addFilter,
    onRemove: table.removeFilter,
  });

  return (
    <div className="flex flex-wrap items-center gap-2">
      {/* A floor on the field's width, so a full row wraps its right-hand
          group onto a second line rather than crushing search to a stub. */}
      <InputGroup className="min-w-0 flex-1 sm:min-w-56 sm:max-w-xs" size="sm">
        <InputGroupAddon align="inline-start">
          <SearchIcon />
        </InputGroupAddon>
        <InputGroupInput
          aria-label="Search users"
          onChange={(event) => patchFilters({ search: event.target.value })}
          placeholder="Search name or email…"
          type="search"
          value={filters.search}
        />
      </InputGroup>

      <div
        className="hidden flex-wrap items-center gap-2 sm:flex"
        ref={row.rowRef}
      >
        {visibleKeys(filters, added).map((key) => (
          <UserFilterPill
            autoOpen={key === row.opening}
            filters={filters}
            key={key}
            onChange={patchFilters}
            onPin={table.addFilter}
            onRemove={row.remove}
            pillKey={key}
          />
        ))}

        <AddFilterMenu
          items={addableKeys(filters, added).map((key) => ({
            key,
            label: filterDef(key).label,
          }))}
          onAdd={row.add}
        />

        {hasActiveFilters(filters) && (
          <Button
            className="text-muted-foreground hover:text-foreground"
            onClick={table.clearFilters}
            size="sm"
            variant="ghost"
          >
            <XIcon />
            Clear all
          </Button>
        )}
      </div>

      <div className="hidden shrink-0 items-center gap-2 sm:ml-auto sm:flex">
        <ColumnsMenu
          columns={columns}
          hidden={table.hiddenColumns}
          onToggle={table.toggleColumn}
        />
        <Button
          disabled={exportDisabled}
          onClick={exportCsv}
          size="sm"
          variant="outline"
        >
          <DownloadIcon />
          Export
        </Button>
        <SortMenu
          defaultDirection={defaultDirection}
          directionLabel={directionLabel}
          keys={SORT_KEYS}
          onSortChange={table.setSort}
          sort={table.sort}
        />
      </div>

      <div className="shrink-0 sm:hidden">
        <AdminFiltersDrawer
          filters={filters}
          onChange={patchFilters}
          onSortChange={table.setSort}
          sort={table.sort}
          view={{
            columns,
            exportDisabled,
            hiddenColumns: table.hiddenColumns,
            onExport: exportCsv,
            onToggleColumn: table.toggleColumn,
            rowCount: table.result.total,
          }}
        />
      </div>
    </div>
  );
}

/**
 * Named value formatters.
 *
 * Panels take `format="money"` rather than a `formatter` function, because the
 * installed entry point of this block is `app/dashboard/page.tsx` — a server
 * component. A function cannot cross that boundary: React rejects it at render
 * time. A block that taught `formatter={(v) => …}` would teach a pattern that
 * breaks the moment someone installs it.
 */

export type ValueFormat = "compact" | "money" | "number" | "percent";

const NUMBER = new Intl.NumberFormat("en-US");
const COMPACT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 1,
  notation: "compact",
});
const MONEY = new Intl.NumberFormat("en-US", {
  currency: "USD",
  maximumFractionDigits: 0,
  style: "currency",
});
const PERCENT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 1,
  style: "percent",
});

const FORMATTERS: Record<ValueFormat, (value: number) => string> = {
  compact: (value) => COMPACT.format(value),
  money: (value) => MONEY.format(value),
  number: (value) => NUMBER.format(value),
  percent: (value) => PERCENT.format(value),
};

/**
 * `null` stays `null` all the way to the em dash.
 *
 * Coercing with `Number(value)` turns an absent measurement into `0`, which
 * then prints as "$0" or "0%" — a reading the data never took. The distinction
 * between "nothing happened" and "we did not measure" is worth the extra
 * branch.
 */
export function toValue(value: unknown): number | null {
  if (value == null) {
    return null;
  }
  const numeric = typeof value === "number" ? value : Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

export function formatValue(
  value: unknown,
  format: ValueFormat = "number"
): string {
  const numeric = toValue(value);
  return numeric === null ? "—" : FORMATTERS[format](numeric);
}

/**
 * The chart layer for this block, ported from shadcn's `chart.tsx`.
 *
 * Vendored into the block rather than added to `@keystoneui/react` on purpose:
 * it needs recharts, and the library stays dependency-light. A block may carry
 * npm dependencies of its own -- `tickets-01` already does, with `@dnd-kit`.
 *
 * Most of the value is the ~20 `[&_.recharts-*]` overrides on `ChartContainer`,
 * which make recharts' hardcoded `#ccc` and `#fff` marks respect the theme.
 * That list is archaeology, not something to re-derive.
 *
 * Two changes from upstream shadcn, both load-bearing:
 *
 *  - `aspect-auto`, not `aspect-video`. Under an explicit pixel height the
 *    upstream class produces a 462px floor and a horizontal document
 *    scrollbar.
 *  - `min-w-0` added, because a chart is a grid or flex child and those
 *    default to `min-content`.
 *
 * `ChartLegend`/`ChartLegendContent` are dropped: `series-legend.tsx` ships a
 * toggleable legend, so recharts' own `<Legend>` never mounts, and leaving the
 * dead path in would mean two legends to pick between.
 */
"use client";

import * as React from "react";
import type { TooltipValueType } from "recharts";
import * as RechartsPrimitive from "recharts";
import { cn } from "@/lib/utils";

/**
 * Format: { THEME_NAME: CSS_SELECTOR }.
 *
 * Upstream emits a `.dark [data-chart=id]` block as well, so a config can carry
 * a literal colour per mode. Ours never does -- `seriesColor()` returns a
 * `var(--chart-N)` *reference*, and the token already re-steps for dark -- so
 * the second block would be textually identical to the first. One entry.
 */
const THEMES = { light: "" } as const;

const INITIAL_DIMENSION = { width: 320, height: 200 } as const;
type TooltipNameType = number | string;

export type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode;
    icon?: React.ComponentType;
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>;

type ChartContextProps = {
  config: ChartConfig;
};

const ChartContext = React.createContext<ChartContextProps | null>(null);

function useChart() {
  const context = React.useContext(ChartContext);

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />");
  }

  return context;
}

function ChartContainer({
  id,
  className,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig;
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"];
  initialDimension?: {
    width: number;
    height: number;
  };
}) {
  const uniqueId = React.useId();
  const chartId = `chart-${id ?? uniqueId.replace(/:/g, "")}`;

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "flex aspect-auto min-w-0 justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-sector]:outline-hidden [&_.recharts-surface]:outline-hidden",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer
          initialDimension={initialDimension}
        >
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme ?? config.color
  );

  if (!colorConfig.length) {
    return null;
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ??
      itemConfig.color;
    return color ? `  --color-${key}: ${color};` : null;
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  );
};

const ChartTooltip = RechartsPrimitive.Tooltip;

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  color,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean;
    hideIndicator?: boolean;
    indicator?: "line" | "dot" | "dashed";
    nameKey?: string;
    labelKey?: string;
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart();

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null;
    }

    const [item] = payload;
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`;
    const itemConfig = getPayloadConfigFromPayload(config, item, key);
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : itemConfig?.label;

    if (labelFormatter) {
      return (
        <div className={cn("font-medium", labelClassName)}>
          {labelFormatter(value, payload)}
        </div>
      );
    }

    if (!value) {
      return null;
    }

    return <div className={cn("font-medium", labelClassName)}>{value}</div>;
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ]);

  if (!(active && payload?.length)) {
    return null;
  }

  const nestLabel = payload.length === 1 && indicator !== "dot";

  return (
    <div
      className={cn(
        "grid min-w-32 items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl",
        className
      )}
    >
      {nestLabel ? null : tooltipLabel}
      <div className="grid gap-1.5">
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`;
            const itemConfig = getPayloadConfigFromPayload(config, item, key);
            const indicatorColor = color ?? item.payload?.fill ?? item.color;

            return (
              <div
                key={index}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center"
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-[2px] border-(--color-border) bg-(--color-bg)",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            }
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center"
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label ?? item.name}
                        </span>
                      </div>
                      {item.value != null && (
                        <span className="font-medium font-mono text-foreground tabular-nums">
                          {typeof item.value === "number"
                            ? item.value.toLocaleString()
                            : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            );
          })}
      </div>
    </div>
  );
}

function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return;
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined;

  let configLabelKey: string = key;

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string;
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string;
  }

  return configLabelKey in config ? config[configLabelKey] : config[key];
}

export { ChartContainer, ChartStyle, ChartTooltip, ChartTooltipContent };

"use client";

import { SlidersHorizontalIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

/**
 * Which columns the table shows.
 *
 * Checkbox items that keep the menu open: hiding three columns is three
 * clicks, not three trips through a trigger. The columns that identify a row —
 * the id or name, the selection checkbox, the row's actions — are not listed,
 * because a table without them is a table you cannot act on.
 *
 * A view preference, not part of the query: it stays out of the URL, since a
 * link you send someone should show them the same rows, not your layout.
 */
export function ColumnsMenu<C extends string>({
  columns,
  hidden,
  onToggle,
}: {
  columns: readonly { id: C; label: string }[];
  hidden: ReadonlySet<C>;
  onToggle: (id: C) => void;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button size="sm" variant="outline" />}>
        <SlidersHorizontalIcon />
        Columns
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-44">
        <DropdownMenuGroup>
          <DropdownMenuLabel>Show columns</DropdownMenuLabel>
          {columns.map((column) => (
            <DropdownMenuCheckboxItem
              checked={!hidden.has(column.id)}
              closeOnClick={false}
              key={column.id}
              onCheckedChange={() => onToggle(column.id)}
            >
              {column.label}
            </DropdownMenuCheckboxItem>
          ))}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * CSV for a spreadsheet, not a person.
 *
 * Each table lists its own columns; the quoting and the download are here so
 * they are written once.
 */

export type CsvColumn<Row> = readonly [
  header: string,
  read: (row: Row) => string,
];

const NEEDS_QUOTES = /[",\r\n]/;
const FORMULA_START = /^[=+\-@\t\r]/;
const NUMBER = /^[+-]?\d+(\.\d+)?$/;

/**
 * One field: neutralised, then quoted per RFC 4180 only when it holds a comma,
 * quote or line break.
 *
 * Neutralised because a spreadsheet runs a cell that starts with `=`, `+`, `-`
 * or `@` as a formula, and these exports carry text people typed — a name of
 * `=HYPERLINK(…)` would become a live link in whoever opens the file. A leading
 * `'` makes Excel and Sheets read it as text. A plain number is left alone, so
 * `-5` stays a number someone can sum.
 */
function csvField(raw: string): string {
  const value = FORMULA_START.test(raw) && !NUMBER.test(raw) ? `'${raw}` : raw;
  return NEEDS_QUOTES.test(value) ? `"${value.replaceAll('"', '""')}"` : value;
}

/** A header line, one line per row, CRLF endings and a trailing newline. */
export function toCsv<Row>(
  columns: readonly CsvColumn<Row>[],
  rows: readonly Row[]
): string {
  const lines = [
    columns.map(([header]) => csvField(header)),
    ...rows.map((row) => columns.map(([, read]) => csvField(read(row)))),
  ];
  return `${lines.map((line) => line.join(",")).join("\r\n")}\r\n`;
}

/**
 * Hands the text to the browser as a file. A `Blob` URL and a throwaway `<a>`
 * rather than a `data:` URI, which some browsers cap in length, and revoked
 * straight after so a long session does not hold every export in memory.
 */
export function downloadCsv(filename: string, csv: string) {
  const url = URL.createObjectURL(
    new Blob([csv], { type: "text/csv;charset=utf-8" })
  );
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

/**
 * The date filter, shared by both tables' `Created` filters: Notion's nine
 * operators, relative rules, presets, and the arithmetic under them.
 *
 * A filter is an operator plus what that operator reads: one date (`is`,
 * `is before`, …), two (`is between`), a rule (`is relative to today` —
 * `Past 7 days`, `This month`), or nothing (`is empty`). A rule is stored as a
 * rule and resolved against today each time, so a link to "the past 7 days"
 * still means the past 7 days tomorrow; the presets are rules too.
 *
 * Every conversion here is in local time. `toISOString()` is UTC, so it turns
 * the evening of the 1st into the 2nd anywhere west of Greenwich, and
 * `new Date("2026-07-01")` parses as UTC midnight, which is the 30th anywhere
 * west of it. Both bugs pass every test run in UTC.
 */

export type DateOperator =
  | "after"
  | "before"
  | "between"
  | "empty"
  | "is"
  | "notEmpty"
  | "onOrAfter"
  | "onOrBefore"
  | "relative";

/** Notion's list, in Notion's order. */
export const DATE_OPERATORS: readonly { label: string; value: DateOperator }[] =
  [
    { label: "Is", value: "is" },
    { label: "Is before", value: "before" },
    { label: "Is after", value: "after" },
    { label: "Is on or before", value: "onOrBefore" },
    { label: "Is on or after", value: "onOrAfter" },
    { label: "Is between", value: "between" },
    { label: "Is relative to today", value: "relative" },
    { label: "Is empty", value: "empty" },
    { label: "Is not empty", value: "notEmpty" },
  ];

/** An operator as a badge or trigger reads it: `is before`. */
export function dateOperatorLabel(op: DateOperator): string {
  const label = DATE_OPERATORS.find((item) => item.value === op)?.label ?? "";
  return label.charAt(0).toLowerCase() + label.slice(1);
}

/** The operators that compare against one date. */
const SINGLE: readonly DateOperator[] = [
  "is",
  "before",
  "after",
  "onOrBefore",
  "onOrAfter",
];

export type RelativeUnit = "day" | "month" | "week" | "year";

/**
 * A rule relative to today. `Past` counts back from today, today included;
 * `This` is the calendar period today falls in. There is no `Next`: nothing is
 * created in the future, so it could only ever match nothing.
 */
export type Relative =
  | { count: number; dir: "past"; unit: RelativeUnit }
  | { dir: "this"; unit: RelativeUnit };

export const RELATIVE_UNITS: readonly RelativeUnit[] = [
  "day",
  "week",
  "month",
  "year",
];

/** The filter, whole. `after` is the date the single-date operators read. */
export interface DateFilter {
  after: string;
  before: string;
  op: DateOperator;
  /** A relative rule as the URL writes it — `past.7.day`, `this.week` — or `""`. */
  rel: string;
}

export const EMPTY_DATE_FILTER: DateFilter = {
  after: "",
  before: "",
  op: "between",
  rel: "",
};

/** The rule a relative filter starts with when nothing else says. */
export const DEFAULT_RELATIVE: Relative = { dir: "this", unit: "week" };

// ---------------------------------------------------------------------------
// Local dates
// ---------------------------------------------------------------------------

const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** A local date as `YYYY-MM-DD`. */
export function toIsoDate(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${date.getFullYear()}-${month}-${day}`;
}

/**
 * `YYYY-MM-DD` as local midnight, or `null` for anything else — including a
 * well-formed string naming a day that does not exist, like `2026-02-30`,
 * which `Date` would otherwise roll over into March.
 */
export function fromIsoDate(value: string): Date | null {
  const match = ISO_DATE.exec(value);
  if (!match) {
    return null;
  }
  const [year, month, day] = [
    Number(match[1]),
    Number(match[2]),
    Number(match[3]),
  ];
  const date = new Date(year, month - 1, day);
  return date.getMonth() === month - 1 && date.getDate() === day ? date : null;
}

/** Calendar days, not 24-hour steps: a DST day is 23 or 25 hours long. */
function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

function daysInMonth(year: number, month: number): number {
  return new Date(year, month + 1, 0).getDate();
}

/** The same day `months` back, clamped: 31 Mar minus a month is 28/29 Feb. */
function monthsBack(date: Date, months: number): Date {
  const target = new Date(date.getFullYear(), date.getMonth() - months, 1);
  const day = Math.min(
    date.getDate(),
    daysInMonth(target.getFullYear(), target.getMonth())
  );
  return new Date(target.getFullYear(), target.getMonth(), day);
}

// ---------------------------------------------------------------------------
// Relative rules
// ---------------------------------------------------------------------------

const RELATIVE_PARAM =
  /^(past)\.(\d{1,3})\.(day|week|month|year)$|^(this)\.(day|week|month|year)$/;

/** `past.7.day` / `this.week` as a rule, or `null` when it is not one. */
export function parseRelative(value: string): Relative | null {
  const match = RELATIVE_PARAM.exec(value);
  if (!match) {
    return null;
  }
  if (match[1]) {
    const count = Number(match[2]);
    return count >= 1
      ? { count, dir: "past", unit: match[3] as RelativeUnit }
      : null;
  }
  return { dir: "this", unit: match[5] as RelativeUnit };
}

export function relativeToParam(rel: Relative): string {
  return rel.dir === "past"
    ? `past.${rel.count}.${rel.unit}`
    : `this.${rel.unit}`;
}

/** `Past 7 days`, `Past week`, `This month`, `Today`. */
export function relativeLabel(rel: Relative): string {
  if (rel.dir === "this") {
    return rel.unit === "day" ? "Today" : `This ${rel.unit}`;
  }
  return rel.count === 1
    ? `Past ${rel.unit}`
    : `Past ${rel.count} ${rel.unit}s`;
}

/**
 * The days a rule covers on `today`, both ends included.
 *
 * `Past 7 days` is seven calendar days ending today. Notion's runs eight — its
 * "past week" on the 10th starts on the 3rd — which is a day more than the
 * label says. Weeks start on Monday, as the calendar does.
 */
export function resolveRelative(
  rel: Relative,
  today: Date
): { after: string; before: string } {
  const range = (from: Date, to: Date) => ({
    after: toIsoDate(from),
    before: toIsoDate(to),
  });
  const year = today.getFullYear();
  const month = today.getMonth();

  if (rel.dir === "this") {
    switch (rel.unit) {
      case "day":
        return range(today, today);
      case "week": {
        // getDay() is 0 for Sunday; Monday starts the week.
        const monday = addDays(today, -((today.getDay() + 6) % 7));
        return range(monday, addDays(monday, 6));
      }
      case "month":
        return range(new Date(year, month, 1), new Date(year, month + 1, 0));
      default:
        return range(new Date(year, 0, 1), new Date(year, 11, 31));
    }
  }

  switch (rel.unit) {
    case "day":
      return range(addDays(today, -(rel.count - 1)), today);
    case "week":
      return range(addDays(today, -(7 * rel.count - 1)), today);
    case "month":
      return range(addDays(monthsBack(today, rel.count), 1), today);
    default:
      return range(addDays(monthsBack(today, 12 * rel.count), 1), today);
  }
}

// ---------------------------------------------------------------------------
// Presets
// ---------------------------------------------------------------------------

export interface DatePreset {
  label: string;
  rel: Relative;
}

/** Presets are rules: a label and the relative filter it sets. */
export function datePresets(rules: readonly Relative[]): DatePreset[] {
  return rules.map((rel) => ({ label: relativeLabel(rel), rel }));
}

/** The preset a filter is exactly, if any. */
export function presetFor(
  filter: DateFilter,
  presets: readonly DatePreset[]
): DatePreset | null {
  if (filter.op !== "relative") {
    return null;
  }
  return (
    presets.find((preset) => relativeToParam(preset.rel) === filter.rel) ?? null
  );
}

/** A preset as a filter. */
export function presetFilter(preset: DatePreset): DateFilter {
  return {
    after: "",
    before: "",
    op: "relative",
    rel: relativeToParam(preset.rel),
  };
}

// ---------------------------------------------------------------------------
// Reading a filter
// ---------------------------------------------------------------------------

/** The rule a relative filter holds, falling back to the default one. */
export function relativeOf(filter: DateFilter): Relative {
  return parseRelative(filter.rel) ?? DEFAULT_RELATIVE;
}

/** Whether the filter narrows anything. */
export function isDateFilterSet(filter: DateFilter): boolean {
  switch (filter.op) {
    case "empty":
    case "notEmpty":
      return true;
    case "relative":
      return parseRelative(filter.rel) !== null;
    case "between":
      return Boolean(filter.after || filter.before);
    default:
      return Boolean(filter.after);
  }
}

/**
 * The days a filter highlights on a calendar — the range a rule resolves to,
 * or the picked dates — or `null` when there is nothing to show.
 */
export function highlightOf(
  filter: DateFilter,
  today: Date
): { after: string; before: string } | null {
  if (filter.op === "relative") {
    const rel = parseRelative(filter.rel);
    return rel ? resolveRelative(rel, today) : null;
  }
  if (filter.op === "between") {
    return filter.after || filter.before
      ? {
          after: filter.after || filter.before,
          before: filter.before || filter.after,
        }
      : null;
  }
  if (SINGLE.includes(filter.op) && filter.after) {
    return { after: filter.after, before: filter.after };
  }
  return null;
}

/**
 * Whether a row's date (`YYYY-MM-DD`, or `""` for none) passes. An operator
 * with nothing picked narrows nothing, the same as every other filter.
 */
export function matchesDate(
  value: string,
  filter: DateFilter,
  today: Date
): boolean {
  const { after, before, op } = filter;
  switch (op) {
    case "empty":
      return value === "";
    case "notEmpty":
      return value !== "";
    case "relative": {
      const rel = parseRelative(filter.rel);
      if (!rel) {
        return true;
      }
      const range = resolveRelative(rel, today);
      return value >= range.after && value <= range.before;
    }
    case "between":
      return (!after || value >= after) && (!before || value <= before);
    default:
      if (!after) {
        return true;
      }
      if (op === "is") {
        return value === after;
      }
      if (op === "before") {
        return value !== "" && value < after;
      }
      if (op === "after") {
        return value > after;
      }
      if (op === "onOrBefore") {
        return value !== "" && value <= after;
      }
      return value >= after;
  }
}

/**
 * What the pill reads after its label, or `null` when unset. `is`,
 * `is between` and a rule go unsaid — a single date, a range and `Past 7 days`
 * each say what they are — so only a qualifier earns words, which is
 * `dateQualifier`'s job.
 */
export function dateFilterValue(filter: DateFilter): string | null {
  if (!isDateFilterSet(filter)) {
    return null;
  }
  switch (filter.op) {
    case "empty":
      return "Empty";
    case "notEmpty":
      return "Not empty";
    case "relative":
      return relativeLabel(relativeOf(filter));
    default:
      return dateOperand(filter);
  }
}

/** The operator the pill names, when it is not one that goes unsaid. */
export function dateQualifier(filter: DateFilter): string | null {
  if (!isDateFilterSet(filter)) {
    return null;
  }
  return ["before", "after", "onOrBefore", "onOrAfter"].includes(filter.op)
    ? dateOperatorLabel(filter.op)
    : null;
}

/**
 * The value with its operator taken out, for a row that shows the operator as
 * a badge of its own — `Created [is before] 2026-07-01`. `null` where there is
 * no value to show beside the badge (`is empty`).
 */
export function dateOperand(filter: DateFilter): string | null {
  if (!isDateFilterSet(filter)) {
    return null;
  }
  switch (filter.op) {
    case "empty":
    case "notEmpty":
      return null;
    case "relative":
      return relativeLabel(relativeOf(filter));
    case "between": {
      const { after, before } = filter;
      if (after && before) {
        return after === before ? after : `${after} – ${before}`;
      }
      return after ? `${after} – any` : `any – ${before}`;
    }
    default:
      return filter.after;
  }
}

// ---------------------------------------------------------------------------
// Changing a filter
// ---------------------------------------------------------------------------

/**
 * Switching operator, as the new filter. Each drops what it does not read, so
 * nothing narrows the table that the label no longer mentions — the rule
 * `setAmountOp` keeps — but the date you were looking at carries over: a range
 * switched to `is before` keeps its start, a rule switched to `is between`
 * becomes the dates it covers today.
 */
export function setDateOperator(
  filter: DateFilter,
  op: DateOperator,
  today: Date
): DateFilter {
  const shown = highlightOf(filter, today);
  if (op === "empty" || op === "notEmpty") {
    return { after: "", before: "", op, rel: "" };
  }
  if (op === "relative") {
    const rel =
      filter.op === "relative" ? filter.rel : relativeToParam(DEFAULT_RELATIVE);
    return { after: "", before: "", op, rel };
  }
  if (op === "between") {
    return {
      after: shown?.after ?? "",
      before: shown?.before ?? "",
      op,
      rel: "",
    };
  }
  return { after: shown?.after ?? "", before: "", op, rel: "" };
}

/** A new rule for a relative filter. */
/**
 * Clearing the value but keeping the operator — what a step's or popover's
 * `Clear` does, as opposed to removing the filter. Only the single-date
 * operators have a value apart from their operator to clear; a rule *is* its
 * value, and `is empty` has none, so those go back to the default filter
 * rather than keeping an operator that would show a rule while narrowing
 * nothing.
 */
export function clearDateValue(filter: DateFilter): DateFilter {
  return SINGLE.includes(filter.op)
    ? { after: "", before: "", op: filter.op, rel: "" }
    : EMPTY_DATE_FILTER;
}

export function setRelative(filter: DateFilter, rel: Relative): DateFilter {
  return {
    ...filter,
    after: "",
    before: "",
    op: "relative",
    rel: relativeToParam(rel),
  };
}

/**
 * A tap on the calendar in `Between` mode.
 *
 * One tap is a day, a second makes it a range (in whichever order they came),
 * and a tap on a finished range starts again. react-day-picker's own range
 * logic instead moves whichever end is nearer, so a third tap quietly
 * shortens the range you had; and its reset option starts a range with an
 * open end, which — since the drawer applies live — would show every row after
 * that day until the second tap. This never leaves an end open that you did
 * not open.
 */
export function nextBetween(
  bounds: { after: string; before: string },
  day: string
): { after: string; before: string } {
  const { after, before } = bounds;
  if (after && before && after !== before) {
    return { after: day, before: day };
  }
  const held = after || before;
  if (!held) {
    return { after: day, before: day };
  }
  if (held === day) {
    return after && before
      ? { after: "", before: "" }
      : { after: day, before: day };
  }
  return held < day
    ? { after: held, before: day }
    : { after: day, before: held };
}

/**
 * A tap on the calendar. The single-date operators set their date, and
 * tapping the date already set takes it off; a rule gives way to the day
 * tapped, as `is` — the calendar is where you go to name a day.
 */
export function tapDay(filter: DateFilter, day: string): DateFilter {
  switch (filter.op) {
    case "between":
      return { ...nextBetween(filter, day), op: "between", rel: "" };
    case "relative":
    case "empty":
    case "notEmpty":
      return { after: day, before: "", op: "is", rel: "" };
    default:
      return {
        after: filter.after === day ? "" : day,
        before: "",
        op: filter.op,
        rel: "",
      };
  }
}

// ---------------------------------------------------------------------------
// The URL
// ---------------------------------------------------------------------------

const OPERATOR_VALUES = DATE_OPERATORS.map((item) => item.value);

/** The filter as URL parameters, defaults left out. */
export function dateFilterToParams(filter: DateFilter): Record<string, string> {
  if (!isDateFilterSet(filter)) {
    return { createdOp: "", from: "", rel: "", to: "" };
  }
  return {
    // `between` goes unsaid only with both ends: an open one would read back
    // as the `on or after` an older link means.
    createdOp:
      filter.op === "between" && filter.after && filter.before ? "" : filter.op,
    from: filter.op === "relative" ? "" : filter.after,
    rel: filter.op === "relative" ? filter.rel : "",
    to: filter.op === "between" ? filter.before : "",
  };
}

/**
 * The inverse, validating every value. Links written before the operators
 * existed carry only `from` / `to`; they read as the range they always meant —
 * both ends `is between`, one end `is on or after` / `is on or before`.
 */
export function dateFilterFromParams(params: URLSearchParams): DateFilter {
  const date = (key: string) => {
    const value = params.get(key) ?? "";
    return fromIsoDate(value) ? value : "";
  };
  const from = date("from");
  const to = date("to");
  const named = params.get("createdOp");
  const op = OPERATOR_VALUES.includes(named as DateOperator)
    ? (named as DateOperator)
    : null;

  if (op === "relative") {
    const rel = params.get("rel") ?? "";
    return parseRelative(rel)
      ? { after: "", before: "", op, rel }
      : EMPTY_DATE_FILTER;
  }
  if (op === "empty" || op === "notEmpty") {
    return { after: "", before: "", op, rel: "" };
  }
  if (op && op !== "between") {
    return { after: from, before: "", op, rel: "" };
  }
  if (!op && from && !to) {
    return { after: from, before: "", op: "onOrAfter", rel: "" };
  }
  if (!op && to && !from) {
    return { after: to, before: "", op: "onOrBefore", rel: "" };
  }
  return { after: from, before: to, op: "between", rel: "" };
}

/**
 * The fixture's today.
 *
 * The mock rows end on 28 Aug 2026, so against the real date every recent
 * preset — `Today`, `Past 7 days` — would open onto an empty table, and every
 * test that picks one would start failing the day the data aged out of it. In
 * your app this is `new Date()`.
 */
export const TODAY = new Date(2026, 7, 28);

"use client";

import { useState } from "react";
import {
  type DateFilter,
  type DatePreset,
  fromIsoDate,
  highlightOf,
  presetFilter,
  presetFor,
  RELATIVE_UNITS,
  type Relative,
  type RelativeUnit,
  relativeOf,
  setRelative,
  tapDay,
  toIsoDate,
} from "@/components/date-filter";
import { Collapse } from "@/components/drawer-parts";
import { Calendar } from "@/components/ui/calendar";
import { Input } from "@/components/ui/input";
import {
  NativeSelect,
  NativeSelectOption,
} from "@/components/ui/native-select";
import { Toggle } from "@/components/ui/toggle";

interface DateFilterStepProps {
  filter: DateFilter;
  onChange: (filter: DateFilter) => void;
  presets: readonly DatePreset[];
  /**
   * Where it sits. A phone sheet gives it the drawer's 16px gutters and boxes
   * the calendar like the sheet's lists; a desktop popover has its own padding
   * and surface, so it takes neither.
   */
  surface: "popover" | "sheet";
  today: Date;
}

/**
 * The body of a date filter, on either surface: the presets, the pickers for
 * a relative rule, and a calendar.
 *
 * The operator is not in here — it is the header's, a badge on the phone and a
 * menu on the desktop — and every change applies at once, so there is no
 * `Apply` either.
 *
 * The calendar always shows what the filter covers: the picked day or range,
 * or the days a rule resolves to today, so `Past 7 days` is something you can
 * see. Tapping a day under a rule turns it into `is` that day.
 */
export function DateFilterStep({
  filter,
  onChange,
  presets,
  surface,
  today,
}: DateFilterStepProps) {
  const shown = highlightOf(filter, today);
  const [month, setMonth] = useState<Date>(
    () => fromIsoDate(shown?.before ?? "") ?? today
  );
  const active = presetFor(filter, presets);
  const sheet = surface === "sheet";
  const gutter = sheet ? "mx-4" : "";

  const pick = (next: DateFilter) => {
    const range = highlightOf(next, today);
    const end = fromIsoDate(range?.before ?? "");
    if (end) {
      setMonth(end);
    }
    onChange(next);
  };

  const blank = filter.op === "empty" || filter.op === "notEmpty";
  // The gap under each part, inside its collapse so a closed part takes none.
  const gap = sheet ? "pb-3" : "pb-2";

  // On a phone the presets are one swipeable row above the calendar; a mouse
  // cannot swipe, and most cannot scroll sideways without Shift, so on the
  // desktop they wrap into a footer under it instead — every one visible, the
  // way the calendar docs' presets sit.
  const presetRow = (
    <fieldset
      className={
        sheet
          ? `min-w-0 ${gap}`
          : "-mx-2 mt-2 -mb-1 min-w-0 border-border-muted border-t px-3 pt-3 pb-2"
      }
    >
      <legend className="sr-only">Presets</legend>
      <div
        className={
          sheet
            ? `ks-scroll-fade-x ${gutter} flex gap-2 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden`
            : "flex flex-wrap gap-2"
        }
      >
        {presets.map((preset) => (
          <Toggle
            className="h-(--ks-control-xs,1.5rem) min-w-0 shrink-0 rounded-sm px-2.5 text-xs"
            key={preset.label}
            // Pressing the active preset again keeps it: these are choices.
            onPressedChange={() => pick(presetFilter(preset))}
            pressed={active?.label === preset.label}
            size="sm"
            variant="outline"
          >
            {preset.label}
          </Toggle>
        ))}
      </div>
    </fieldset>
  );

  // Each part that comes and goes with the operator opens and closes in
  // place (see `Collapse`), so switching to `is relative to today` slides the
  // calendar down under its pickers instead of jumping it 44px, and on the
  // desktop the popover resizes rather than snapping.
  return (
    <div className={sheet ? "pb-4" : "pb-1"}>
      {sheet ? presetRow : null}

      <Collapse open={filter.op === "relative"}>
        <RelativePicker
          className={`${gutter} ${gap}`}
          onChange={(rel) => pick(setRelative(filter, rel))}
          rel={relativeOf(filter)}
        />
      </Collapse>

      <Collapse open={blank}>
        <p
          className={`${sheet ? "px-4" : "px-2"} ${gap} text-muted-foreground text-sm`}
        >
          {filter.op === "notEmpty"
            ? "Matches every row with a date."
            : "Matches rows with no date."}
        </p>
      </Collapse>

      <Collapse open={!blank}>
        <FilterCalendar
          filter={filter}
          month={month}
          onChange={onChange}
          onMonthChange={setMonth}
          sheet={sheet}
          today={today}
        />
      </Collapse>

      {sheet ? null : presetRow}
    </div>
  );
}

/**
 * The calendar: a range for `is between` and for a rule, a single day for the
 * rest, always showing what the filter covers today.
 */
function FilterCalendar({
  filter,
  month,
  onChange,
  onMonthChange,
  sheet,
  today,
}: {
  filter: DateFilter;
  month: Date;
  onChange: (filter: DateFilter) => void;
  onMonthChange: (month: Date) => void;
  sheet: boolean;
  today: Date;
}) {
  const shown = highlightOf(filter, today);
  const start = fromIsoDate(shown?.after ?? "") ?? undefined;
  const end = fromIsoDate(shown?.before ?? "") ?? undefined;
  const onDay = (date: Date | undefined) => {
    if (date) {
      onChange(tapDay(filter, toIsoDate(date)));
    }
  };
  // Both kinds of calendar share everything but their selection.
  const calendar = {
    captionLayout: "dropdown" as const,
    className: sheet
      ? "mx-auto bg-transparent p-0 [--cell-size:min(--spacing(10),calc(100cqw/7))]"
      : // 36px, near the calendar docs' 38: the caption row is one cell
        // tall, and at the default 30px the 32px month/year selects stuck out.
        "mx-auto bg-transparent p-0 [--cell-size:--spacing(9)]",
    classNames: sheet
      ? { month: "flex w-full flex-col gap-2", week: "mt-0.5 flex w-full" }
      : undefined,
    // Nothing is created tomorrow.
    disabled: { after: today },
    endMonth: today,
    fixedWeeks: true,
    month,
    onMonthChange,
    startMonth: new Date(today.getFullYear() - 10, 0, 1),
    today,
    // Monday, so "This week" and the calendar agree on where a week starts.
    weekStartsOn: 1 as const,
  };

  return (
    <div
      className={
        sheet ? "mx-4 rounded-xl bg-muted p-3 dark:bg-muted/50" : undefined
      }
    >
      {/* On the sheet's `muted` box, light mode remaps `muted` to the page
          colour so today and a range's middle stay visible on it. */}
      <div
        className={
          sheet ? "@container not-dark:[--muted:var(--background)]" : undefined
        }
      >
        {filter.op === "between" || filter.op === "relative" ? (
          <Calendar
            {...calendar}
            mode="range"
            onSelect={(_range, date) => onDay(date)}
            selected={start ? { from: start, to: end } : undefined}
          />
        ) : (
          <Calendar
            {...calendar}
            mode="single"
            onSelect={(_day, date) => onDay(date)}
            selected={start}
          />
        )}
      </div>
    </div>
  );
}

const UNIT_LABELS: Record<RelativeUnit, [string, string]> = {
  day: ["day", "days"],
  month: ["month", "months"],
  week: ["week", "weeks"],
  year: ["year", "years"],
};

/**
 * `Past [7] [days]` / `This [week]` — Notion's pickers, minus `Next`, which on
 * a creation date could only match nothing.
 */
function RelativePicker({
  className,
  onChange,
  rel,
}: {
  className: string;
  onChange: (rel: Relative) => void;
  rel: Relative;
}) {
  const plural = rel.dir === "past" && rel.count !== 1 ? 1 : 0;
  return (
    <div className={`flex items-center gap-2 ${className}`}>
      <NativeSelect
        aria-label="Relative to today"
        className="w-24"
        onChange={(event) =>
          onChange(
            event.target.value === "this"
              ? { dir: "this", unit: rel.unit }
              : { count: 1, dir: "past", unit: rel.unit }
          )
        }
        size="sm"
        value={rel.dir}
      >
        <NativeSelectOption value="past">Past</NativeSelectOption>
        <NativeSelectOption value="this">This</NativeSelectOption>
      </NativeSelect>
      {rel.dir === "past" && (
        <Input
          aria-label="How many"
          className="w-16"
          inputMode="numeric"
          min={1}
          onChange={(event) => {
            const count = Number.parseInt(event.target.value, 10);
            if (count >= 1 && count <= 999) {
              onChange({ ...rel, count });
            }
          }}
          size="sm"
          type="number"
          value={rel.count}
        />
      )}
      <NativeSelect
        aria-label="Unit"
        className="flex-1"
        onChange={(event) =>
          onChange({ ...rel, unit: event.target.value as RelativeUnit })
        }
        size="sm"
        value={rel.unit}
      >
        {RELATIVE_UNITS.map((unit) => (
          <NativeSelectOption key={unit} value={unit}>
            {UNIT_LABELS[unit][plural]}
          </NativeSelectOption>
        ))}
      </NativeSelect>
    </div>
  );
}

"use client";

import { EllipsisIcon, TrashIcon } from "lucide-react";
import {
  clearDateValue,
  DATE_OPERATORS,
  type DateFilter,
  type DateOperator,
  type DatePreset,
  dateOperatorLabel,
  setDateOperator,
} from "@/components/date-filter";
import { DateFilterStep } from "@/components/date-filter-step";
import { FilterTrigger } from "@/components/filter-trigger";
import { PillShell, PillValue } from "@/components/pill-shell";
import { OperatorMenu } from "@/components/set-pill";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

/**
 * A date filter as a pill — `Created is before: 2026-07-01`, `Created: Past
 * 7 days` — opening Notion's arrangement: the dimension and its operator menu
 * in the header, "Delete filter" behind `⋯`, and under them the same presets,
 * relative pickers and calendar the phone's step shows.
 */
export function DatePill({
  autoOpen = false,
  empty,
  filter,
  label,
  onChange,
  onRemove,
  presets,
  qualifier,
  today,
  value,
}: {
  autoOpen?: boolean;
  empty: string;
  filter: DateFilter;
  label: string;
  onChange: (filter: DateFilter) => void;
  onRemove: (trigger: HTMLElement | null) => void;
  presets: readonly DatePreset[];
  /** The operator the trigger names, when it is not one that goes unsaid. */
  qualifier: string | null;
  today: Date;
  /** The value as the pill reads it, or `null` when unset. */
  value: string | null;
}) {
  return (
    <PillShell label={label} onRemove={onRemove}>
      {({ keyDown, remove }) => (
        <Popover defaultOpen={autoOpen}>
          <PopoverTrigger
            render={
              <FilterTrigger
                active={value !== null}
                label={label}
                onKeyDown={keyDown}
                operator={qualifier}
                removable
              />
            }
          >
            <PillValue empty={empty} value={value} />
          </PopoverTrigger>
          <PopoverContent align="start" className="w-72 p-1">
            <div className="flex items-center gap-1 py-1 ps-2 pe-1">
              <span className="text-muted-foreground text-sm">{label}</span>
              <OperatorMenu
                label={dateOperatorLabel(filter.op)}
                onValueChange={(next) =>
                  onChange(setDateOperator(filter, next as DateOperator, today))
                }
                options={DATE_OPERATORS}
                value={filter.op}
              />
              {/* Clears the date and keeps the operator, as Player's and
                  Amount's popovers do; "Delete filter" removes it outright.
                  In the header, so it costs the calendar no row. */}
              <span className="ms-auto" />
              {value === null ? null : (
                <Button
                  onClick={() => onChange(clearDateValue(filter))}
                  size="xs"
                  variant="ghost"
                >
                  Clear
                </Button>
              )}
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <Button
                      aria-label="More actions"
                      className="text-muted-foreground"
                      size="icon-xs"
                      variant="ghost"
                    />
                  }
                >
                  <EllipsisIcon />
                </DropdownMenuTrigger>
                <DropdownMenuContent
                  align="end"
                  className="min-w-44"
                  size="compact"
                >
                  <DropdownMenuItem onClick={remove} variant="destructive">
                    <TrashIcon />
                    Delete filter
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
            <div className="px-1 pb-1">
              <DateFilterStep
                filter={filter}
                onChange={onChange}
                presets={presets}
                surface="popover"
                today={today}
              />
            </div>
          </PopoverContent>
        </Popover>
      )}
    </PillShell>
  );
}

"use client";

import { PlusIcon, TrashIcon } from "lucide-react";
import { type ReactNode, useRef, useState } from "react";
import { Bound } from "@/components/drawer-parts";
import { FilterTrigger } from "@/components/filter-trigger";
import { PillShell, PillValue, useHoverless } from "@/components/pill-shell";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

/**
 * The pill row's parts, shared by both tables.
 *
 * Each table owns its filter vocabulary — `payment-filters.ts`,
 * `admin-filters.ts` — and composes these with it. Nothing here knows what a
 * payment or a user is, which is what lets the two toolbars be one design
 * rather than two that drift.
 */

export interface PillOption {
  label: string;
  value: string;
}

/** What every pill takes, whatever it opens. */
interface PillBase {
  /**
   * Mount with the popup already open. Set on the pill just added from
   * `+ Add filter`: you picked "Status" because you want to filter by status,
   * so making you click the new pill as well is a wasted step. Read once, on
   * mount — after that the popup is the pill's own business.
   */
  autoOpen?: boolean;
  /** What the pill reads when nothing is set: "All" for a set, "Any" for a range. */
  empty: string;
  /** The dimension, shown muted ahead of the value. */
  label: string;
  /** Takes the pill off the row. Handed its trigger, for focus. */
  onRemove: (trigger: HTMLElement | null) => void;
  /** The value as the pill reads it, or `null` when the filter is unset. */
  value: string | null;
}

/**
 * A single-select filter — `Status: Failed`.
 *
 * Its X takes the chevron's slot on hover and keyboard focus, so the pill never
 * changes width, and Backspace removes it from the keyboard. Touch screens have
 * no hover, so their way off is a "Delete filter" row in the menu.
 *
 * Picking `All` never takes a pill off the row: removing the control from under
 * the cursor mid-interaction is worse than a pill that reads `All`. Removal is
 * always its own, explicit action.
 */
export function OptionPill({
  autoOpen = false,
  empty,
  label,
  onRemove,
  onSelect,
  options,
  selected,
  value,
}: PillBase & {
  onSelect: (value: string) => void;
  options: readonly PillOption[];
  /** The selected option's `value`, which the radio group checks. */
  selected: string;
}) {
  return (
    <PillShell label={label} onRemove={onRemove}>
      {({ keyDown, remove }) => (
        <DropdownMenu defaultOpen={autoOpen}>
          <DropdownMenuTrigger
            render={
              <FilterTrigger
                active={value !== null}
                label={label}
                onKeyDown={keyDown}
                removable
              />
            }
          >
            {/* Unset reads as a placeholder rather than a value, which is what
                separates the pills doing something from those merely present. */}
            <PillValue empty={empty} value={value} />
          </DropdownMenuTrigger>
          <DropdownMenuContent
            align="start"
            className="min-w-44"
            size="compact"
          >
            <DropdownMenuGroup>
              <DropdownMenuRadioGroup onValueChange={onSelect} value={selected}>
                {options.map((option) => (
                  <DropdownMenuRadioItem
                    key={option.value}
                    value={option.value}
                  >
                    {option.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuGroup>
            <TouchDeleteItem onRemove={remove} />
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </PillShell>
  );
}

/**
 * A date range needs two fields at once, so it opens a `Popover` rather than a
 * menu. A menu is a list of choices; a pair of bounds is a tiny form.
 */
export function DateRangePill({
  after,
  autoOpen = false,
  before,
  empty,
  id,
  label,
  onAfterChange,
  onBeforeChange,
  onClear,
  onRemove,
  value,
}: PillBase & {
  after: string;
  before: string;
  /** Prefixes the two fields' ids, which must be unique on the page. */
  id: string;
  onAfterChange: (value: string) => void;
  onBeforeChange: (value: string) => void;
  onClear: () => void;
}) {
  const touch = useHoverless();

  return (
    <PillShell label={label} onRemove={onRemove}>
      {({ keyDown, remove }) => (
        <Popover defaultOpen={autoOpen}>
          <PopoverTrigger
            render={
              <FilterTrigger
                active={value !== null}
                label={label}
                onKeyDown={keyDown}
                removable
              />
            }
          >
            <PillValue empty={empty} value={value} />
          </PopoverTrigger>
          <PopoverContent align="start" className="w-72">
            <div className="flex flex-col gap-3">
              <div className="grid grid-cols-2 gap-3">
                <Bound
                  id={`${id}-min`}
                  // From / To, not After / Before: both ends are inclusive,
                  // and "After 1 Jul" would read as excluding the 1st.
                  label="From"
                  onChange={onAfterChange}
                  type="date"
                  value={after}
                />
                <Bound
                  id={`${id}-max`}
                  label="To"
                  onChange={onBeforeChange}
                  type="date"
                  value={before}
                />
              </div>
              {value !== null && (
                <div className="flex justify-end">
                  <Button onClick={onClear} size="xs" variant="ghost">
                    Clear
                  </Button>
                </div>
              )}
              {/* The popover's version of `TouchDeleteItem`. */}
              {touch && (
                <Button
                  className="w-full justify-start text-destructive"
                  onClick={remove}
                  variant="ghost"
                >
                  <TrashIcon />
                  Delete filter
                </Button>
              )}
            </div>
          </PopoverContent>
        </Popover>
      )}
    </PillShell>
  );
}

/**
 * The touch screen's way to remove a pill: no hover means no X, so the menu
 * carries a "Delete filter" row instead.
 *
 * Only on devices that cannot hover: on a pointer device it would be a second
 * copy of the X.
 */
function TouchDeleteItem({ onRemove }: { onRemove: () => void }) {
  const touch = useHoverless();
  if (!touch) {
    return null;
  }

  return (
    <>
      <DropdownMenuSeparator />
      <DropdownMenuItem onClick={onRemove} variant="destructive">
        <TrashIcon />
        Delete filter
      </DropdownMenuItem>
    </>
  );
}

/** The `+ Add filter` menu, holding whatever is not already on the toolbar. */
export function AddFilterMenu<K extends string>({
  items,
  onAdd,
}: {
  items: readonly { key: K; label: string }[];
  onAdd: (key: K) => void;
}): ReactNode {
  const picked = useRef(false);

  if (items.length === 0) {
    return null;
  }

  return (
    <DropdownMenu>
      {/* A lucide `Plus` rather than a literal "+": next to the `X` on Clear
          all, a text glyph would sit at a different weight and baseline. */}
      <DropdownMenuTrigger
        render={<Button data-add-filter="" size="sm" variant="ghost" />}
      >
        <PlusIcon />
        Add filter
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="start"
        className="min-w-44"
        // Picking a filter opens that filter's own popup, which takes focus;
        // returning it to this button would pull it straight back out. Closed
        // any other way — Escape, a click outside — focus comes home as usual.
        finalFocus={() => {
          const wasPick = picked.current;
          picked.current = false;
          return !wasPick;
        }}
        size="compact"
      >
        <DropdownMenuGroup>
          {items.map((item) => (
            <DropdownMenuItem
              key={item.key}
              onClick={() => {
                picked.current = true;
                onAdd(item.key);
              }}
            >
              {item.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * The row's add and remove, with the focus handling both need.
 *
 * Adding remembers which pill to mount open. Removing unmounts the element
 * holding focus, which would drop focus to <body> — a keyboard user's place in
 * the page, gone. So the target is picked *before* the removal: the next pill
 * along, or, past the last one, `Add filter`, which is where the removed filter
 * has just gone back to.
 */
export function usePillRow<K extends string>({
  onAdd,
  onRemove,
}: {
  onAdd: (key: K) => void;
  onRemove: (key: K) => void;
}) {
  const rowRef = useRef<HTMLDivElement>(null);
  // The filter most recently picked from `+ Add filter`, whose pill mounts open.
  const [opening, setOpening] = useState<K | null>(null);

  const add = (key: K) => {
    setOpening(key);
    onAdd(key);
  };

  const remove = (key: K, trigger: HTMLElement | null) => {
    const row = rowRef.current;
    const all = [
      ...(row?.querySelectorAll<HTMLElement>("[data-filter-pill]") ?? []),
    ];
    const next = all[all.indexOf(trigger as HTMLElement) + 1] ?? null;
    onRemove(key);
    // After the commit, and after Base UI has run its own focus return to a
    // trigger that no longer exists.
    requestAnimationFrame(() => {
      const target = next?.isConnected
        ? next
        : row?.querySelector<HTMLElement>("[data-add-filter]");
      target?.focus();
    });
  };

  return { add, opening, remove, rowRef };
}

/**
 * Which pills a toolbar shows, for any filter vocabulary.
 *
 * Both tables declare their filters as a list of `{ key, value }`
 * descriptors; these read that list, so the users and payments rows decide
 * what is on show by the same rule.
 */

export interface FilterDescriptor<K extends string, F> {
  key: K;
  /** The value as the pill reads it, or `null` when the filter is unset. */
  value: (filters: F) => string | null;
}

/**
 * The pills on the row: the ones added (or there from the start), then any
 * filter that holds a value without a pill — set from the phone drawer, or
 * from a link. A filter that narrows the table is never invisible.
 */
export function visibleKeys<K extends string, F>(
  defs: readonly FilterDescriptor<K, F>[],
  filters: F,
  added: readonly K[]
): K[] {
  const valued = defs
    .filter((def) => def.value(filters) !== null && !added.includes(def.key))
    .map((def) => def.key);
  return [...added, ...valued];
}

/** Filters still available to add — the `+ Add filter` menu's contents. */
export function addableKeys<K extends string, F>(
  defs: readonly FilterDescriptor<K, F>[],
  filters: F,
  added: readonly K[]
): K[] {
  const visible = visibleKeys(defs, filters, added);
  return defs.filter((def) => !visible.includes(def.key)).map((def) => def.key);
}

