import {
  ChevronDownIcon,
  CircleXIcon,
  EllipsisIcon,
  TrashIcon,
} from "lucide-react";
import { type RefObject, useRef } from "react";
import { FilterTrigger } from "@/components/filter-trigger";
import { PillShell, PillValue } from "@/components/pill-shell";
import { Button } from "@/components/ui/button";
import {
  Combobox,
  ComboboxChip,
  ComboboxChips,
  ComboboxChipsInput,
  ComboboxEmpty,
  ComboboxItem,
  ComboboxList,
  ComboboxValue,
} from "@/components/ui/combobox";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

/**
 * A set filter with an operator — `Status is not: Failed, +1` — and the two
 * parts it is made of, the header's operator menu and the multi-select list.
 *
 * Nothing here knows what a payment or a user is. The payments chip uses the
 * parts for Currency and Status beside its Amount and Player fields; the users
 * table, whose only set filter is Status, uses `SetPill` whole.
 */

/**
 * A set filter as a pill: the trigger names the dimension and, when it is not
 * the default, the operator; the popover's header holds the operator menu and
 * "Delete filter" behind `⋯`, and the list under it holds the picks. The same
 * arrangement as the payments operator chip, so the two tables' Status pills
 * are one control.
 */
export function SetPill<T extends string>({
  autoOpen = false,
  empty,
  itemLabel,
  items,
  label,
  noun,
  onRemove,
  onSelectedChange,
  operator,
  selected,
  value,
}: {
  autoOpen?: boolean;
  empty: string;
  itemLabel: (item: T) => string;
  items: readonly T[];
  label: string;
  /** The plural for the field's accessible names: `statuses`. */
  noun: string;
  onRemove: (trigger: HTMLElement | null) => void;
  onSelectedChange: (next: T[]) => void;
  operator: OperatorMenuProps;
  selected: readonly T[];
  /** The value as the pill reads it, or `null` when nothing is picked. */
  value: string | null;
}) {
  const field = useRef<HTMLInputElement>(null);
  // An operator with nothing to compare narrows nothing, so the trigger only
  // names a qualifier once something is picked: never "Status is not: All".
  const qualifier =
    value !== null && operator.value !== operator.options[0]?.value
      ? operator.label
      : null;

  return (
    <PillShell label={label} onRemove={onRemove}>
      {({ keyDown, remove }) => (
        <Popover defaultOpen={autoOpen}>
          <PopoverTrigger
            render={
              <FilterTrigger
                active={value !== null}
                label={label}
                onKeyDown={keyDown}
                operator={qualifier}
                removable
              />
            }
          >
            <PillValue empty={empty} value={value} />
          </PopoverTrigger>
          <PopoverContent
            align="start"
            className="w-64 p-1"
            initialFocus={() => field.current ?? true}
          >
            <div className="flex items-center gap-1 py-1 ps-2 pe-1">
              <span className="text-muted-foreground text-sm">{label}</span>
              <OperatorMenu {...operator} />
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <Button
                      aria-label="More actions"
                      className="ms-auto text-muted-foreground"
                      size="icon-xs"
                      variant="ghost"
                    />
                  }
                >
                  <EllipsisIcon />
                </DropdownMenuTrigger>
                <DropdownMenuContent
                  align="end"
                  className="min-w-44"
                  size="compact"
                >
                  <DropdownMenuItem onClick={remove} variant="destructive">
                    <TrashIcon />
                    Delete filter
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
            <SetOptions
              field={field}
              items={items}
              label={itemLabel}
              noun={noun}
              onValueChange={onSelectedChange}
              value={selected}
            />
          </PopoverContent>
        </Popover>
      )}
    </PillShell>
  );
}

export interface OperatorMenuProps {
  label: string;
  onValueChange: (value: string) => void;
  options: readonly { label: string; value: string }[];
  value: string;
}

/** The operator in the header: the current one, opening onto the rest. */
export function OperatorMenu({
  label,
  onValueChange,
  options,
  value,
}: OperatorMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            aria-label={`Operator: ${label}`}
            className="gap-1 px-1.5 font-semibold text-sm"
            size="xs"
            variant="ghost"
          />
        }
      >
        {label}
        <ChevronDownIcon className="size-3.5 text-muted-foreground" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="min-w-36" size="compact">
        <DropdownMenuRadioGroup
          onValueChange={(next) => onValueChange(next as string)}
          value={value}
        >
          {options.map((option) => (
            <DropdownMenuRadioItem key={option.value} value={option.value}>
              {option.label}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * The selection as chips in a field, the options not yet picked listed under
 * it — Notion's multi-select. The chips are the answer to "what is held", read
 * in place rather than counted, and the field filters the list as you type.
 *
 * An inline `Combobox` — `inline open` keeps its list in this popover instead
 * of opening a popup of its own on top of it. So `ComboboxList` and
 * `ComboboxItem` are used bare: `ComboboxContent` always portals.
 *
 * Picked options stay in the list and gain a check, as Notion's do. Removing
 * them would shuffle every row below the one just clicked, so the next pick
 * lands on the wrong option; and clicking a checked one again unpicks it,
 * which a list of only the unpicked could never offer.
 *
 * The round X clears every chip but keeps the operator — you emptied the
 * list, not the comparison.
 */
export function SetOptions<T extends string>({
  field,
  items,
  label,
  noun,
  onValueChange,
  value,
}: {
  field: RefObject<HTMLInputElement | null>;
  items: readonly T[];
  /** What a value reads as: `In progress` for `in-progress`. */
  label: (item: T) => string;
  /** The plural the field's accessible names use: `currencies`. */
  noun: string;
  onValueChange: (next: T[]) => void;
  value: readonly T[];
}) {
  return (
    <Combobox
      autoHighlight
      inline
      itemToStringLabel={(item: T) => label(item)}
      items={items}
      multiple
      onValueChange={(next: T[]) => onValueChange(next)}
      open
      value={[...value]}
    >
      <div className="px-1 pb-2">
        {/* 32px: the toolbar's tier. `ComboboxChips` defaults to the 40px
            form-field height, which towers over the compact rows below. */}
        <ComboboxChips className="min-h-8 py-0.5 pe-1">
          <ComboboxValue>
            {(values: T[]) => (
              <>
                {values.map((item) => (
                  <ComboboxChip key={item}>{label(item)}</ComboboxChip>
                ))}
                <ComboboxChipsInput
                  aria-label={`Search ${noun}`}
                  placeholder={values.length > 0 ? "" : "Search…"}
                  ref={field}
                />
              </>
            )}
          </ComboboxValue>
          {value.length > 0 && (
            <Button
              aria-label={`Clear ${noun}`}
              className="ms-auto shrink-0 rounded-full text-muted-foreground"
              onClick={() => onValueChange([])}
              size="icon-xs"
              variant="ghost"
            >
              <CircleXIcon />
            </Button>
          )}
        </ComboboxChips>
      </div>
      <ComboboxEmpty className="px-2 py-1.5 text-muted-foreground text-sm">
        No match
      </ComboboxEmpty>
      <ComboboxList className="max-h-none p-0" data-size="compact">
        {(item: T) => (
          <ComboboxItem key={item} value={item}>
            {label(item)}
          </ComboboxItem>
        )}
      </ComboboxList>
    </Combobox>
  );
}

"use client";

import { XIcon } from "lucide-react";
import type { KeyboardEvent, ReactNode } from "react";
import { useRef, useSyncExternalStore } from "react";
import { X_SWAP } from "@/components/filter-trigger";
import { cn } from "@/lib/utils";

export interface ShellControls {
  /** Backspace / Delete on the trigger removes the filter. */
  keyDown: (event: KeyboardEvent<HTMLElement>) => void;
  remove: () => void;
}

/**
 * Wraps a pill's trigger with the X that swaps in for its chevron.
 *
 * The X is the trigger's sibling, not its child: a button inside a button is
 * invalid HTML and leaves the inner one unreachable to assistive tech. It sits
 * absolutely over the chevron's 16px slot — `end-3` is the `sm` button's `px-3`
 * — so showing it changes nothing about the pill's width.
 *
 * It is out of the tab order. Keyboard users have Backspace on the trigger,
 * which is announced through `aria-keyshortcuts`; one stop per pill keeps
 * tabbing along a row of eight pills at eight stops rather than sixteen.
 *
 * Every pill has one, the starting pair included, so the X means the same
 * thing wherever it appears. The label says which filter, "Remove Provider
 * filter", for the same reason the row actions do.
 */
export function PillShell({
  children,
  label,
  onRemove,
}: {
  children: (controls: ShellControls) => ReactNode;
  /** The filter's dimension, for the X's accessible name. */
  label: string;
  /** Handed the pill's trigger, so focus can move before it unmounts. */
  onRemove: (trigger: HTMLElement | null) => void;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const remove = () =>
    onRemove(
      ref.current?.querySelector<HTMLElement>("[data-filter-pill]") ?? null
    );
  const keyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (
      (event.key === "Backspace" || event.key === "Delete") &&
      !event.defaultPrevented &&
      event.currentTarget.getAttribute("aria-expanded") !== "true"
    ) {
      event.preventDefault();
      remove();
    }
  };

  return (
    <span className="group/pill relative inline-flex" ref={ref}>
      {children({ keyDown, remove })}
      <button
        aria-label={`Remove ${label} filter`}
        className={cn(
          "absolute end-3 top-1/2 z-10 grid size-4 -translate-y-1/2 cursor-pointer place-items-center rounded-sm text-muted-foreground before:absolute before:-inset-1 hover:bg-foreground/10 hover:text-foreground",
          X_SWAP
        )}
        data-filter-remove=""
        onClick={remove}
        tabIndex={-1}
        type="button"
      >
        <XIcon className="size-3.5" />
      </button>
    </span>
  );
}

/**
 * The pill's value, in its own slot so the set and unset cases are the same
 * element rather than a span and a bare text node — which is what lets a test
 * compare their colours at all.
 */
export function PillValue({
  empty,
  value,
}: {
  empty: string;
  value: string | null;
}) {
  return (
    <span
      className={value === null ? "font-normal text-muted-foreground" : ""}
      data-pill-value=""
    >
      {value ?? empty}
    </span>
  );
}

const HOVERLESS = "(hover: none)";

/**
 * Whether the device has no hover, and so never sees the X swap.
 *
 * Local to the block rather than `@keystoneui/react/hooks`: blocks install as
 * copies, and that subpath has no registry item to land at. The usual objection
 * to a media-query hook — it has to guess on the server and flip after
 * hydration — does not bite here, because its only callers render inside a
 * popup, which mounts on open, long after hydration.
 */
export function useHoverless(): boolean {
  return useSyncExternalStore(
    (onChange) => {
      const query = matchMedia(HOVERLESS);
      query.addEventListener("change", onChange);
      return () => query.removeEventListener("change", onChange);
    },
    () => matchMedia(HOVERLESS).matches,
    () => false
  );
}

/**
 * How much of the result set is on screen.
 *
 * Shared between this block's two tables, which asked the same question with
 * the same arithmetic and differed only in the noun.
 *
 * It is not what the pagination status says: `Page 2 of 2` reads the same
 * whether that page holds ten rows or the three left over. Nor is it the
 * selection count — `SelectionBar` already states that, at every width, where
 * `TablePaginationInfo` is `hidden lg:block`.
 *
 * Deliberately a block file rather than a library prop. `TablePaginationInfo`
 * already accepts `children`, which is the composition answer, and the whole
 * of the rest is two lines of arithmetic and a plural.
 */
export function ResultSummary({
  noun,
  pageIndex,
  pageSize,
  rowCount,
  totalCount,
}: {
  /** Singular and plural, because English will not derive one from the other. */
  noun: [string, string];
  pageIndex: number;
  pageSize: number;
  rowCount: number;
  totalCount: number;
}) {
  if (totalCount === 0) {
    return null;
  }

  const first = pageIndex * pageSize + 1;
  const last = pageIndex * pageSize + rowCount;

  return (
    <>
      Showing {first}–{last} of {totalCount}{" "}
      {totalCount === 1 ? noun[0] : noun[1]}
    </>
  );
}

"use client";

import { cn } from "@/lib/utils";

export interface SeriesDef {
  /** Slot 1-5 in the chart ramp. Omit to take the position in the list. */
  color?: number;
  key: string;
  label: string;
  /**
   * Use a named token instead of a ramp slot, e.g. `"muted-foreground"`.
   *
   * The escape hatch matters: an "Other" or "Unclassified" band is not a
   * category, and giving it a categorical hue claims one exists where there is
   * only missing evidence.
   */
  token?: string;
}

/**
 * The single place a series' colour is decided.
 *
 * Both the mark and the legend swatch resolve through this, so they cannot
 * disagree — a legend that says one thing while the band says another is worse
 * than no legend.
 */
export function seriesColor(item: SeriesDef, index: number): string {
  if (item.token) {
    return `var(--${item.token})`;
  }
  return `var(--chart-${item.color ?? (index % 5) + 1})`;
}

interface SeriesLegendProps {
  hidden: ReadonlySet<string>;
  onToggle: (key: string) => void;
  series: readonly SeriesDef[];
}

export function SeriesLegend({ hidden, onToggle, series }: SeriesLegendProps) {
  const visible = series.filter((item) => !hidden.has(item.key)).length;

  return (
    <ul className="flex flex-wrap items-center gap-x-4 gap-y-1">
      {/* Rendered from `series`, never from recharts' payload: the payload
          drops hidden entries, which would give you a chart you can narrow and
          then never widen again. */}
      {series.map((item, index) => {
        const off = hidden.has(item.key);
        // An empty chart is not a view of anything, and a reader cannot tell it
        // from "no data" — so the last visible series refuses to switch off.
        const locked = !off && visible === 1;

        return (
          <li key={item.key}>
            <button
              aria-pressed={!off}
              className={cn(
                "inline-flex cursor-pointer items-center gap-1.5 rounded-sm text-xs transition-colors focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2",
                off
                  ? "text-muted-foreground line-through opacity-60"
                  : "text-foreground",
                locked && "cursor-not-allowed"
              )}
              disabled={locked}
              onClick={() => onToggle(item.key)}
              title={
                locked ? "At least one series has to stay visible" : undefined
              }
              type="button"
            >
              <span
                aria-hidden="true"
                className="size-2.5 shrink-0 rounded-[2px]"
                style={{ backgroundColor: seriesColor(item, index) }}
              />
              {item.label}
            </button>
          </li>
        );
      })}
    </ul>
  );
}

"use client";

import { Skeleton } from "@/components/ui/skeleton";
import { TableCell, TableRow } from "@/components/ui/table";

/**
 * Placeholder rows while the table's request is in flight.
 *
 * Built to the real rows' height so nothing moves when the data lands: the
 * actions cell holds a 32px box — the `icon-sm` trigger the real row has — and
 * a two-line column (a name over an email) gets two bars at the real lines'
 * heights. The count is the previous page's, so a refetch does not
 * collapse the table to a single row and spring back.
 *
 * Hidden from assistive tech: the table's `aria-busy` is what says "loading".
 * Grey bars announced cell by cell would be noise.
 */
export function SkeletonRows({
  checkbox = false,
  columns,
  count,
  twoLine,
}: {
  checkbox?: boolean;
  /** Data columns between the checkbox and the actions. */
  columns: number;
  count: number;
  /** The data column, by index, that holds two lines of text. */
  twoLine?: number;
}) {
  // Placeholders have no identity of their own; position is the only key.
  return Array.from({ length: count }, (_row, row) => (
    // biome-ignore lint/suspicious/noArrayIndexKey: placeholders, keyed by slot
    <TableRow aria-hidden data-skeleton-row="" key={row}>
      {checkbox ? (
        <TableCell>
          <Skeleton className="size-4" />
        </TableCell>
      ) : null}
      {Array.from({ length: columns }, (_column, column) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: placeholders, keyed by slot
        <TableCell key={column}>
          {column === twoLine ? (
            <div className="flex flex-col">
              <div className="flex h-5 items-center">
                <Skeleton className="h-3.5 w-28" />
              </div>
              <div className="flex h-4 items-center">
                <Skeleton className="h-3 w-40" />
              </div>
            </div>
          ) : (
            <div className="flex h-5 items-center">
              {/* Varied widths so the column does not read as a grid of
                  identical bricks. */}
              <Skeleton className={WIDTHS[(row + column) % WIDTHS.length]} />
            </div>
          )}
        </TableCell>
      ))}
      <TableCell>
        <div className="size-8" />
      </TableCell>
    </TableRow>
  ));
}

const WIDTHS = ["h-3.5 w-24", "h-3.5 w-16", "h-3.5 w-20", "h-3.5 w-12"];

"use client";

import { ArrowDownIcon, ArrowUpDownIcon, ArrowUpIcon } from "lucide-react";
import type { ReactNode } from "react";
import {
  directionsFor,
  type SortDirection,
  type SortState,
} from "@/components/sort";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { TableHead, TableSortButton } from "@/components/ui/table";

const DIRECTION_ICON = { asc: ArrowUpIcon, desc: ArrowDownIcon } as const;

/**
 * The toolbar's Sort menu: which column, then which way.
 *
 * Two radio groups rather than every column × direction pair, so flipping the
 * direction does not mean finding the column again. A new column takes its
 * natural direction, and the direction list leads with it, so the common pick
 * is always the first one. The directions are named for the column —
 * `Newest first`, `A–Z` — because "ascending" says nothing about what you will
 * see.
 *
 * It writes the same `sort` the column headers do, so a header click moves this
 * menu's check and the other way round, with no syncing code.
 */
export function SortMenu<K extends string>({
  defaultDirection,
  directionLabel,
  keys,
  onSortChange,
  sort,
}: {
  defaultDirection: (key: K) => SortDirection;
  directionLabel: (key: K, direction: SortDirection) => string;
  keys: readonly { id: K; label: string }[];
  onSortChange: (sort: SortState<K>) => void;
  sort: SortState<K>;
}) {
  const label = keys.find((option) => option.id === sort.key)?.label ?? "Sort";

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button size="sm" variant="outline" />}>
        <ArrowUpDownIcon />
        <span className="font-normal text-muted-foreground">Sort:</span>
        {label}
        <span className="font-normal text-muted-foreground">
          ({directionLabel(sort.key, sort.direction)})
        </span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-52">
        <DropdownMenuGroup>
          <DropdownMenuLabel>Sort by</DropdownMenuLabel>
          <DropdownMenuRadioGroup
            onValueChange={(value) => {
              const key = value as K;
              onSortChange({ direction: defaultDirection(key), key });
            }}
            value={sort.key}
          >
            {keys.map((option) => (
              <DropdownMenuRadioItem key={option.id} value={option.id}>
                {option.label}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuGroup>
          <DropdownMenuRadioGroup
            onValueChange={(value) =>
              onSortChange({ direction: value as SortDirection, key: sort.key })
            }
            value={sort.direction}
          >
            {directionsFor(defaultDirection(sort.key)).map((direction) => {
              const Icon = DIRECTION_ICON[direction];
              return (
                <DropdownMenuRadioItem key={direction} value={direction}>
                  <Icon />
                  {directionLabel(sort.key, direction)}
                </DropdownMenuRadioItem>
              );
            })}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * A sortable column header.
 *
 * Clicking an inactive column sorts it in its natural direction — the same
 * `defaultDirection` the Sort menu uses, so a header and the menu agree on
 * what picking a column means. Clicking the active one flips it. There is no
 * third, unsorted click: these tables always have an order.
 *
 * Only on columns that sort. A column that does not passes no `sortDirection`
 * to its `TableHead` at all — `null` would claim it sorts and is merely
 * inactive, and put `aria-sort` on a header that does nothing.
 */
export function SortableHead<K extends string>({
  children,
  className,
  columnKey,
  defaultDirection,
  numeric,
  onSortChange,
  sort,
}: {
  children: ReactNode;
  className?: string;
  columnKey: K;
  defaultDirection: (key: K) => SortDirection;
  numeric?: boolean;
  onSortChange: (sort: SortState<K>) => void;
  sort: SortState<K>;
}) {
  const active = sort.key === columnKey;
  const direction = active ? sort.direction : null;
  const flipped: SortDirection = sort.direction === "asc" ? "desc" : "asc";

  return (
    <TableHead
      className={className}
      numeric={numeric}
      sortDirection={direction}
    >
      <TableSortButton
        direction={direction}
        onClick={() =>
          onSortChange({
            direction: active ? flipped : defaultDirection(columnKey),
            key: columnKey,
          })
        }
      >
        {children}
      </TableSortButton>
    </TableHead>
  );
}

/** Sort state shared by both tables, the Sort menu and the column headers. */

export type SortDirection = "asc" | "desc";

export interface SortState<K extends string> {
  direction: SortDirection;
  key: K;
}

/** Both directions, the column's natural one first — the order the menu lists. */
export function directionsFor(natural: SortDirection): SortDirection[] {
  return natural === "asc" ? ["asc", "desc"] : ["desc", "asc"];
}

import type { SortDirection, SortState } from "@/components/sort";

/**
 * Reading a table's query back out of a URL.
 *
 * A URL is input someone can type, so every reader here validates and falls
 * back rather than trusting it: `?status=bogus` opens the table unfiltered,
 * not broken. Writers leave defaults out, so an untouched table has a clean
 * URL and a shared link carries only what was changed.
 */

/** `value` if it is one of `allowed`, otherwise `fallback`. */
export function oneOf<T extends string>(
  value: string | null,
  allowed: readonly T[],
  fallback: T
): T {
  return allowed.includes(value as T) ? (value as T) : fallback;
}

/** `amount.desc` — the column and the way, in one readable parameter. */
export function sortToParam<K extends string>(
  sort: SortState<K>,
  fallback: SortState<K>
): string {
  return sort.key === fallback.key && sort.direction === fallback.direction
    ? ""
    : `${sort.key}.${sort.direction}`;
}

export function sortFromParam<K extends string>(
  value: string | null,
  keys: readonly K[]
): SortState<K> | undefined {
  const [key, direction] = (value ?? "").split(".");
  if (
    !(keys.includes(key as K) && (direction === "asc" || direction === "desc"))
  ) {
    return;
  }
  return { direction: direction as SortDirection, key: key as K };
}

/** One-based in the URL, because that is what the footer says. */
export function pageToParams(
  pageIndex: number,
  pageSize: number,
  defaultSize: number
): { page: string; size: string } {
  return {
    page: pageIndex > 0 ? String(pageIndex + 1) : "",
    size: pageSize === defaultSize ? "" : String(pageSize),
  };
}

export function pageFromParams(
  params: URLSearchParams,
  sizes: readonly number[]
): { pageIndex?: number; pageSize?: number } {
  const page = Number(params.get("page"));
  const size = Number(params.get("size"));
  return {
    pageIndex: Number.isInteger(page) && page > 1 ? page - 1 : undefined,
    pageSize: sizes.includes(size) ? size : undefined,
  };
}

"use client";

import { useEffect, useMemo, useState } from "react";
import type { SortState } from "@/components/sort";

/**
 * Everything a filterable, sortable, paged, selectable table holds, for both of
 * this block's tables.
 *
 * One hook rather than two copies of the same dozen `useState`s, so the users
 * and payments tables cannot drift apart in how they reset a page or keep a
 * selection. What differs — the rows, the filter vocabulary, how a row matches
 * and sorts — comes in through `config`.
 */
export interface DataTableConfig<Row, F, K extends string, S extends string> {
  /** A filter's reset patch, for removing its pill. */
  clearFor: (key: K) => Partial<F>;
  /** The pills on a fresh row; `Clear all` puts these back. */
  defaultKeys: readonly K[];
  defaultPageSize: number;
  defaultSort: SortState<S>;
  emptyFilters: F;
  /**
   * How long the stand-in request takes. The rows are local, so without one
   * the loading state would never be seen — a real table swaps
   * `useSimulatedFetch` for its data layer and keeps the rest.
   */
  latency?: number;
  matches: (row: Row, filters: F) => boolean;
  rows: readonly Row[];
  sortRows: (rows: readonly Row[], sort: SortState<S>) => Row[];
}

/** The part of the state a URL can carry, and a request would send. */
export interface DataTableQuery<F, S extends string> {
  filters: F;
  pageIndex: number;
  pageSize: number;
  sort: SortState<S>;
}

export interface DataTableResult<Row> {
  /** Every row the filters and sort produce — what Export writes. */
  all: Row[];
  /** The current page of `all`. */
  page: Row[];
  pageCount: number;
  total: number;
}

export function useDataTable<
  Row extends { id: string },
  F,
  K extends string,
  S extends string,
  C extends string = string,
>(config: DataTableConfig<Row, F, K, S>) {
  const [filters, setFilters] = useState<F>(config.emptyFilters);
  const [sort, setSortState] = useState(config.defaultSort);
  const [pageIndex, setPageIndex] = useState(0);
  const [pageSize, setPageSizeState] = useState(config.defaultPageSize);
  // Which pills are on the row: the starting set, plus any added by hand,
  // minus any removed. A filter holding a value shows its pill regardless, so
  // this only decides which empty ones are on show.
  const [added, setAdded] = useState<K[]>(() => [...config.defaultKeys]);
  // Kept across pages and filters: selecting rows on page one, then page two,
  // then exporting is the whole point of a selection that outlives a page.
  const [selected, setSelected] = useState<ReadonlySet<string>>(new Set());
  const [hiddenColumns, setHiddenColumns] = useState<ReadonlySet<C>>(new Set());

  const query: DataTableQuery<F, S> = { filters, pageIndex, pageSize, sort };
  const { loading, result } = useSimulatedFetch(
    query,
    () => run(config, query),
    config.latency ?? 300,
    EMPTY_RESULT as DataTableResult<Row>
  );

  // A page that no longer exists — `?page=9` on a link, or the last row of the
  // last page deleted elsewhere — snaps to the last page that does.
  useEffect(() => {
    if (!loading && pageIndex > result.pageCount - 1) {
      setPageIndex(result.pageCount - 1);
    }
  }, [loading, pageIndex, result.pageCount]);

  // Every change that can shrink the result goes back to the first page:
  // page 2 of the unfiltered list usually does not exist once a filter is on,
  // and "Page 2 of 1" with no rows looks broken.
  const patchFilters = (patch: Partial<F>) => {
    setFilters((current) => ({ ...current, ...patch }));
    setPageIndex(0);
  };

  return {
    added,
    addFilter: (key: K) =>
      setAdded((current) =>
        current.includes(key) ? current : [...current, key]
      ),
    clearFilters: () => {
      setFilters(config.emptyFilters);
      setAdded([...config.defaultKeys]);
      setPageIndex(0);
    },
    clearSelection: () => setSelected(new Set()),
    filters,
    hiddenColumns,
    loading,
    pageIndex,
    pageSize,
    patchFilters,
    query,
    removeFilter: (key: K) => {
      patchFilters(config.clearFor(key));
      setAdded((current) => current.filter((item) => item !== key));
    },
    /** Applies a query read from somewhere else — the URL, on load. */
    restore: (next: Partial<DataTableQuery<F, S>>) => {
      if (next.filters) {
        setFilters(next.filters);
      }
      if (next.sort) {
        setSortState(next.sort);
      }
      if (next.pageSize) {
        setPageSizeState(next.pageSize);
      }
      if (next.pageIndex !== undefined) {
        setPageIndex(next.pageIndex);
      }
    },
    result,
    selected,
    setPageIndex,
    setPageSize: (size: number) => {
      setPageSizeState(size);
      // Page 3 of a 5-per-page list does not exist at 50 per page.
      setPageIndex(0);
    },
    setSort: (next: SortState<S>) => {
      setSortState(next);
      setPageIndex(0);
    },
    sort,
    toggleColumn: (id: C) =>
      setHiddenColumns((current) => toggled(current, id)),
    /** Selects or clears every row on the current page. */
    togglePage: (checked: boolean) =>
      setSelected((current) => {
        const next = new Set(current);
        for (const row of result.page) {
          if (checked) {
            next.add(row.id);
          } else {
            next.delete(row.id);
          }
        }
        return next;
      }),
    toggleRow: (id: string) => setSelected((current) => toggled(current, id)),
  };
}

function toggled<T>(set: ReadonlySet<T>, item: T): ReadonlySet<T> {
  const next = new Set(set);
  if (next.has(item)) {
    next.delete(item);
  } else {
    next.add(item);
  }
  return next;
}

/** What a server would do with the query: filter, sort, count, slice. */
function run<Row, F, K extends string, S extends string>(
  config: DataTableConfig<Row, F, K, S>,
  query: DataTableQuery<F, S>
): DataTableResult<Row> {
  const all = config.sortRows(
    config.rows.filter((row) => config.matches(row, query.filters)),
    query.sort
  );
  const start = query.pageIndex * query.pageSize;
  return {
    all,
    page: all.slice(start, start + query.pageSize),
    pageCount: Math.max(1, Math.ceil(all.length / query.pageSize)),
    total: all.length,
  };
}

const EMPTY_RESULT: DataTableResult<never> = {
  all: [],
  page: [],
  pageCount: 1,
  total: 0,
};

/**
 * Answers a query after `latency`, the way a request would.
 *
 * Each change restarts the wait, so typing in search settles once rather than
 * once per keystroke — the debounce a real search field needs, for free.
 * While waiting, the last answer stays in hand: the pagination and summary keep
 * describing the rows that were there rather than collapsing to zero, and the
 * table body shows skeleton rows in their place.
 *
 * It starts out loading, on the server too, so the first paint is the
 * skeleton rather than a flash of the unfiltered table before a URL's filters
 * apply.
 */
function useSimulatedFetch<Q, R>(
  query: Q,
  answer: () => R,
  latency: number,
  initial: R
): { loading: boolean; result: R } {
  const key = JSON.stringify(query);
  const [settled, setSettled] = useState<{ key: string; result: R } | null>(
    null
  );
  // `answer` is a fresh closure each render; the key is what identifies it.
  // biome-ignore lint/correctness/useExhaustiveDependencies: keyed on `key`
  const pending = useMemo(answer, [key]);

  useEffect(() => {
    const timer = setTimeout(
      () => setSettled({ key, result: pending }),
      latency
    );
    return () => clearTimeout(timer);
  }, [key, latency, pending]);

  return {
    loading: settled?.key !== key,
    result: settled?.result ?? initial,
  };
}

